INSERT INTO certificates (code, category, name_ja, name_vi)
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Máy công cụ và gia công', '工作機械', 'こうさくきかい', 'máy công cụ', '工作機械の保全を行います。', 'こうさくきかいの ほぜんを おこないます。', 'Thực hiện bảo trì máy công cụ.', 1);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Máy công cụ và gia công', 'フライス盤', 'フライスばん', 'máy phay', 'フライス盤で平面削りを行います。', 'フライスばんで へいめんけずりを おこないます。', 'Gia công mặt phẳng bằng máy phay.', 2);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Máy công cụ và gia công', '旋盤', 'せんばん', 'máy tiện', '旋盤で工作物を加工します。', 'せんばんで こうさくぶつを かこうします。', 'Gia công phôi bằng máy tiện.', 3);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Máy công cụ và gia công', 'ボール盤', 'ボールばん', 'máy khoan', 'ボール盤で穴あけ加工を行います。', 'ボールばんで あなあけかこうを おこないます。', 'Gia công khoan lỗ bằng máy khoan.', 4);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Máy công cụ và gia công', '工作物', 'こうさくぶつ', 'phôi', '旋盤で工作物を加工します。', 'せんばんで こうさくぶつを かこうします。', 'Gia công phôi bằng máy tiện.', 5);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Máy công cụ và gia công', '主軸', 'しゅじく', 'trục chính', '主軸に切削工具を取り付けます。', 'しゅじくに せっさくこうぐを とりつけます。', 'Lắp dụng cụ cắt vào trục chính.', 6);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Máy công cụ và gia công', '切削工具', 'せっさくこうぐ', 'dụng cụ cắt', '主軸に切削工具を取り付けます。', 'しゅじくに せっさくこうぐを とりつけます。', 'Lắp dụng cụ cắt vào trục chính.', 7);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Máy công cụ và gia công', '穴あけ加工', 'あなあけかこう', 'gia công khoan lỗ', 'ボール盤で穴あけ加工を行います。', 'ボールばんで あなあけかこうを おこないます。', 'Gia công khoan lỗ bằng máy khoan.', 8);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Máy công cụ và gia công', '平面削り', 'へいめんけずり', 'gia công phay mặt phẳng', 'フライス盤で平面削りを行います。', 'フライスばんで へいめんけずりを おこないます。', 'Gia công mặt phẳng bằng máy phay.', 9);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Máy công cụ và gia công', '溝削り', 'みぞけずり', 'gia công rãnh', '溝削りの前に切削作業の手順を確認します。', 'みぞけずりの まえに せっさくさぎょうの てじゅんを かくにんします。', 'Kiểm tra trình tự công việc cắt gọt trước khi gia công rãnh.', 10);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Máy công cụ và gia công', '切削作業', 'せっさくさぎょう', 'công việc cắt gọt', '溝削りの前に切削作業の手順を確認します。', 'みぞけずりの まえに せっさくさぎょうの てじゅんを かくにんします。', 'Kiểm tra trình tự công việc cắt gọt trước khi gia công rãnh.', 11);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Máy công cụ và gia công', '切削', 'せっさく', 'cắt gọt', '工作物を固定してから切削します。', 'こうさくぶつを こていしてから せっさくします。', 'Cố định phôi rồi mới cắt gọt.', 12);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Máy công cụ và gia công', '加工', 'かこう', 'gia công', '旋盤で工作物を加工します。', 'せんばんで こうさくぶつを かこうします。', 'Gia công phôi bằng máy tiện.', 13);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Máy công cụ và gia công', '固定', 'こてい', 'cố định', '工作物を固定してから切削します。', 'こうさくぶつを こていしてから せっさくします。', 'Cố định phôi rồi mới cắt gọt.', 14);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 1, 'Máy công cụ và gia công', '軸', 'じく', 'trục', '軸がゆっくり回転します。', 'じくが ゆっくり かいてんします。', 'Trục quay chậm.', 15);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Bảo trì, hỏng hóc và độ tin cậy', '保全', 'ほぜん', 'bảo trì/duy trì tình trạng hoạt động', '工作機械の保全を行います。', 'こうさくきかいの ほぜんを おこないます。', 'Thực hiện bảo trì máy công cụ.', 16);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Bảo trì, hỏng hóc và độ tin cậy', '設備', 'せつび', 'thiết bị', '設備と装置を毎日点検します。', 'せつびと そうちを まいにち てんけんします。', 'Kiểm tra thiết bị và bộ máy hằng ngày.', 17);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Bảo trì, hỏng hóc và độ tin cậy', '装置', 'そうち', 'thiết bị', '設備と装置を毎日点検します。', 'せつびと そうちを まいにち てんけんします。', 'Kiểm tra thiết bị và bộ máy hằng ngày.', 18);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Bảo trì, hỏng hóc và độ tin cậy', '事後保全', 'じごほぜん', 'bảo trì sau hỏng', '事後保全では、故障した設備を修理します。', 'じごほぜんでは、こしょうした せつびを しゅうりします。', 'Trong bảo trì sau hỏng, sửa chữa thiết bị đã bị hỏng.', 19);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Bảo trì, hỏng hóc và độ tin cậy', '改良保全', 'かいりょうほぜん', 'bảo trì cải tiến', '改良保全で設備の性能を高めます。', 'かいりょうほぜんで せつびの せいのうを たかめます。', 'Nâng cao tính năng của thiết bị bằng bảo trì cải tiến.', 20);
