    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Bảo trì, hỏng hóc và độ tin cậy', '定期保全', 'ていきほぜん', 'bảo trì định kỳ', '決めた周期で定期保全を行います。', 'きめた しゅうきで ていきほぜんを おこないます。', 'Thực hiện bảo trì định kỳ theo chu kỳ đã xác định.', 22);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Bảo trì, hỏng hóc và độ tin cậy', '予知保全', 'よちほぜん', 'bảo trì dự đoán', '予知保全に必要な情報を集めます。', 'よちほぜんに ひつような じょうほうを あつめます。', 'Thu thập thông tin cần thiết cho bảo trì dự đoán.', 23);
