    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Bảo trì, hỏng hóc và độ tin cậy', '保全活動', 'ほぜんかつどう', 'hoạt động bảo trì', '生産保全のために保全活動を続けます。', 'せいさんほぜんの ために ほぜんかつどうを つづけます。', 'Tiếp tục các hoạt động bảo trì nhằm phục vụ bảo trì sản xuất.', 25);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Bảo trì, hỏng hóc và độ tin cậy', '保全性', 'ほぜんせい', 'tính dễ bảo trì', '設備の保全性を評価します。', 'せつびの ほぜんせいを ひょうかします。', 'Đánh giá khả năng bảo trì của thiết bị.', 26);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Bảo trì, hỏng hóc và độ tin cậy', '故障', 'こしょう', 'hỏng hóc', '事後保全では、故障した設備を修理します。', 'じごほぜんでは、こしょうした せつびを しゅうりします。', 'Trong bảo trì sau hỏng, sửa chữa thiết bị đã bị hỏng.', 27);
