    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Bảo trì, hỏng hóc và độ tin cậy', '変形', 'へんけい', 'biến dạng', '故障モードとして、変形や腐食を記録します。', 'こしょうモードとして、へんけいや ふしょくを きろくします。', 'Ghi lại biến dạng và ăn mòn như các dạng hư hỏng.', 33);
