    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Bảo trì, hỏng hóc và độ tin cậy', '摩耗', 'まもう', 'mài mòn', '軸受部の摩耗を確認します。', 'じくうけぶの まもうを かくにんします。', 'Kiểm tra độ mòn của bộ phận ổ trục.', 35);
