    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Bảo trì, hỏng hóc và độ tin cậy', '摩耗故障期', 'まもうこしょうき', 'giai đoạn hỏng do hao mòn', '摩耗故障期と偶発故障期の違いを学びます。', 'まもうこしょうきと ぐうはつこしょうきの ちがいを まなびます。', 'Học sự khác nhau giữa giai đoạn hỏng do hao mòn và giai đoạn hỏng ngẫu nhiên.', 37);
