    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Bảo trì, hỏng hóc và độ tin cậy', '動作時間', 'どうさじかん', 'thời gian hoạt động', '動作時間と運転時間を記録します。', 'どうさじかんと うんてんじかんを きろくします。', 'Ghi lại thời gian hoạt động và thời gian vận hành.', 40);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 2, 'Bảo trì, hỏng hóc và độ tin cậy', '運転時間', 'うんてんじかん', 'thời gian vận hành', '動作時間と運転時間を記録します。', 'どうさじかんと うんてんじかんを きろくします。', 'Ghi lại thời gian hoạt động và thời gian vận hành.', 41);
