    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 3, 'Quản lý chất lượng và tiêu chuẩn công việc', '機械操作', 'きかいそうさ', 'thao tác máy', '作業者は作業標準書で機械操作の手順を確認します。', 'さぎょうしゃは さぎょうひょうじゅんしょで きかいそうさの てじゅんを かくにんします。', 'Người thao tác kiểm tra trình tự vận hành máy trong tài liệu tiêu chuẩn công việc.', 85);
