    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 4, 'Vật liệu và nhiệt luyện', '熱処理', 'ねつしょり', 'nhiệt luyện', '熱処理では、加熱温度と冷却速度を調節して金属組織を変えます。', 'ねつしょりでは、かねつおんどと れいきゃくそくどを ちょうせつして きんぞくそしきを かえます。', 'Trong nhiệt luyện, điều chỉnh nhiệt độ gia nhiệt và tốc độ làm nguội để thay đổi tổ chức kim loại.', 117);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 4, 'Vật liệu và nhiệt luyện', '加熱温度', 'かねつおんど', 'nhiệt độ nung', '熱処理では、加熱温度と冷却速度を調節して金属組織を変えます。', 'ねつしょりでは、かねつおんどと れいきゃくそくどを ちょうせつして きんぞくそしきを かえます。', 'Trong nhiệt luyện, điều chỉnh nhiệt độ gia nhiệt và tốc độ làm nguội để thay đổi tổ chức kim loại.', 118);
