    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 4, 'Vật liệu và nhiệt luyện', 'めっき', 'めっき', 'mạ bề mặt', '亜鉛めっきの状態を確認します。', 'あえんめっきの じょうたいを かくにんします。', 'Kiểm tra tình trạng lớp mạ kẽm.', 124);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 4, 'Vật liệu và nhiệt luyện', '軟化', 'なんか', 'làm mềm', '焼なましによって鋼を軟化させます。', 'やきなましに よって はがねを なんかさせます。', 'Làm mềm thép bằng phương pháp ủ.', 125);
