    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 9, 'Động từ và cách diễn đạt trong đề', '要した', 'ようした', 'đã cần/đã tiêu tốn', '修理に要した時間を記録します。', 'しゅうりに ようした じかんを きろくします。', 'Ghi lại thời gian đã dùng để sửa chữa.', 346);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 9, 'Động từ và cách diễn đạt trong đề', '記されている', 'しるされている', 'được ghi', '端子に記されている数字を確認します。', 'たんしに しるされている すうじを かくにんします。', 'Kiểm tra các con số được ghi trên đầu cốt.', 347);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 9, 'Động từ và cách diễn đạt trong đề', '予め', 'あらかじめ', 'trước/định trước', '作業前に予め工具を準備します。', 'さぎょうまえに あらかじめ こうぐを じゅんびします。', 'Chuẩn bị sẵn dụng cụ trước khi làm việc.', 348);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 9, 'Động từ và cách diễn đạt trong đề', '容易', 'ようい', 'dễ dàng', '容易に点検できるように配置を変えます。', 'よういに てんけんできるように はいちを かえます。', 'Thay đổi cách bố trí để dễ kiểm tra.', 349);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 9, 'Động từ và cách diễn đạt trong đề', '適した', 'てきした', 'phù hợp', '作業に適した工具を選びます。', 'さぎょうに てきした こうぐを えらびます。', 'Chọn dụng cụ phù hợp với công việc.', 350);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 9, 'Động từ và cách diễn đạt trong đề', '小さい', 'ちいさい', 'nhỏ hơn', '小さい部品を箱に入れます。', 'ちいさい ぶひんを はこに いれます。', 'Cho linh kiện nhỏ vào hộp.', 351);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 9, 'Động từ và cách diễn đạt trong đề', '優れる', 'すぐれる', 'tốt hơn/vượt trội', '耐食性に優れる材料を選びます。', 'たいしょくせいに すぐれる ざいりょうを えらびます。', 'Chọn vật liệu có khả năng chống ăn mòn tốt.', 352);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 9, 'Động từ và cách diễn đạt trong đề', '一般的', 'いっぱんてき', 'nhìn chung', '一般的な故障の原因を学びます。', 'いっぱんてきな こしょうの げんいんを まなびます。', 'Học các nguyên nhân hư hỏng thường gặp.', 353);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 9, 'Động từ và cách diễn đạt trong đề', '時間', 'じかん', 'thời gian', '時間経過に伴う変化を調べ、必要な時間を記録します。', 'じかんけいかに ともなう へんかを しらべ、ひつような じかんを きろくします。', 'Tìm hiểu sự thay đổi theo thời gian và ghi lại thời gian cần thiết.', 354);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 9, 'Động từ và cách diễn đạt trong đề', '時間経過', 'じかんけいか', 'sự trôi qua của thời gian', '時間経過に伴う変化を調べ、必要な時間を記録します。', 'じかんけいかに ともなう へんかを しらべ、ひつような じかんを きろくします。', 'Tìm hiểu sự thay đổi theo thời gian và ghi lại thời gian cần thiết.', 355);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 9, 'Động từ và cách diễn đạt trong đề', '複数枚', 'ふくすうまい', 'nhiều tấm', '複数枚の板を重ねます。', 'ふくすうまいの いたを かさねます。', 'Xếp chồng nhiều tấm lên nhau.', 356);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 9, 'Động từ và cách diễn đạt trong đề', '倍', 'ばい', 'lần', '電流を二倍にした場合の発熱量を計算します。', 'でんりゅうを にばいに した ばあいの はつねつりょうを けいさんします。', 'Tính lượng nhiệt phát sinh khi tăng dòng điện lên gấp đôi.', 357);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 9, 'Động từ và cách diễn đạt trong đề', '過程', 'かてい', 'quá trình', '故障メカニズムを調べ、故障に至る過程を確認します。', 'こしょうメカニズムを しらべ、こしょうに いたる かていを かくにんします。', 'Tìm hiểu cơ chế hư hỏng và kiểm tra quá trình dẫn đến hư hỏng.', 358);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 10, 'Từ bổ sung xuất hiện trong đề', '例', 'れい', 'ví dụ', '故障の例を説明します。', 'こしょうの れいを せつめいします。', 'Giải thích ví dụ về hư hỏng.', 359);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 10, 'Từ bổ sung xuất hiện trong đề', '順序', 'じゅんじょ', 'thứ tự', 'シーケンス制御では、決めた順序で動作を進めます。', 'シーケンスせいぎょでは、きめた じゅんじょで どうさを すすめます。', 'Trong điều khiển trình tự, thực hiện các hoạt động theo thứ tự đã xác định.', 360);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 10, 'Từ bổ sung xuất hiện trong đề', '手続き', 'てつづき', 'thủ tục', '決められた手続きに従って作業します。', 'きめられた てつづきに したがって さぎょうします。', 'Làm việc theo thủ tục đã quy định.', 361);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 10, 'Từ bổ sung xuất hiện trong đề', '段階', 'だんかい', 'giai đoạn', '各段階で安全を確認します。', 'かくだんかいで あんぜんを かくにんします。', 'Kiểm tra an toàn ở từng giai đoạn.', 362);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 10, 'Từ bổ sung xuất hiện trong đề', '逐次', 'ちくじ', 'lần lượt', '機械の動作を逐次確認します。', 'きかいの どうさを ちくじ かくにんします。', 'Kiểm tra lần lượt các hoạt động của máy.', 363);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 10, 'Từ bổ sung xuất hiện trong đề', '位置', 'いち', 'vị trí', 'サーボモータで位置と速度を制御します。', 'サーボモータで いちと そくどを せいぎょします。', 'Điều khiển vị trí và tốc độ bằng động cơ servo.', 364);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 10, 'Từ bổ sung xuất hiện trong đề', 'エミッタ', 'エミッタ', 'emitter/cực phát', 'エミッタの位置を確認します。', 'エミッタの いちを かくにんします。', 'Kiểm tra vị trí của emitter.', 365);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 10, 'Từ bổ sung xuất hiện trong đề', '周波数', 'しゅうはすう', 'tần số', 'インバータで出力の周波数を変えます。', 'インバータで しゅつりょくの しゅうはすうを かえます。', 'Thay đổi tần số đầu ra bằng biến tần.', 366);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 10, 'Từ bổ sung xuất hiện trong đề', '損傷原因', 'そんしょうげんいん', 'nguyên nhân gây hư hại', '軸の折損と損傷原因を調べます。', 'じくの せっそんと そんしょうげんいんを しらべます。', 'Kiểm tra tình trạng gãy trục và nguyên nhân hư hại.', 367);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 10, 'Từ bổ sung xuất hiện trong đề', '物体', 'ぶったい', 'vật thể', '物体の温度を測定します。', 'ぶったいの おんどを そくていします。', 'Đo nhiệt độ của vật thể.', 368);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 10, 'Từ bổ sung xuất hiện trong đề', '天然', 'てんねん', 'tự nhiên', '天然ゴムなどの天然の材料について学びます。', 'てんねんゴムなどの てんねんの ざいりょうについて まなびます。', 'Học về các vật liệu tự nhiên như cao su thiên nhiên.', 369);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 10, 'Từ bổ sung xuất hiện trong đề', '性能', 'せいのう', 'tính năng', '改良保全で設備の性能を高めます。', 'かいりょうほぜんで せつびの せいのうを たかめます。', 'Nâng cao tính năng của thiết bị bằng bảo trì cải tiến.', 370);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 10, 'Từ bổ sung xuất hiện trong đề', '故障実績', 'こしょうじっせき', 'lịch sử hỏng', '故障実績を参考に点検計画を立てます。', 'こしょうじっせきを さんこうに てんけんけいかくを たてます。', 'Lập kế hoạch kiểm tra dựa trên lịch sử hư hỏng.', 371);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 10, 'Từ bổ sung xuất hiện trong đề', '周期', 'しゅうき', 'chu kỳ', '決めた周期で定期保全を行います。', 'きめた しゅうきで ていきほぜんを おこないます。', 'Thực hiện bảo trì định kỳ theo chu kỳ đã xác định.', 372);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 10, 'Từ bổ sung xuất hiện trong đề', '呼ばれる', 'よばれる', 'được gọi là', 'サーボモータと呼ばれるモータの働きを学びます。', 'サーボモータと よばれる モータの はたらきを まなびます。', 'Học chức năng của loại động cơ được gọi là động cơ servo.', 373);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 10, 'Từ bổ sung xuất hiện trong đề', '高温', 'こうおん', 'nhiệt độ cao', '高温になる原因を調べます。', 'こうおんに なる げんいんを しらべます。', 'Tìm hiểu nguyên nhân khiến nhiệt độ tăng cao.', 374);
    INSERT INTO certificate_vocabulary (certificate_id, category_no, category_name, term_ja, reading, meaning_vi, example_ja, example_reading, example_vi, sort_order) VALUES (cert_id, 10, 'Từ bổ sung xuất hiện trong đề', '変換', 'へんかん', 'chuyển đổi', 'インバータで直流を交流に変換します。', 'インバータで ちょくりゅうを こうりゅうに へんかんします。', 'Chuyển đổi điện một chiều thành điện xoay chiều bằng bộ nghịch lưu.', 375);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 1, '下図に示す工作機械は、フライス盤である。', 'Máy công cụ trong hình dưới là máy phay.', TRUE, 'Hình là máy phay: dao quay trên trục chính, phôi được gá trên bàn máy và có chuyển động chạy dao tương đối. Bàn máy và cụm trục chính trong hình khác máy tiện, nơi phôi quay trên trục chính.', '[{"term": "工作機械", "reading": "こうさくきかい", "meaning": "máy công cụ"}, {"term": "フライス盤", "reading": "フライスばん", "meaning": "máy phay"}, {"term": "主軸", "reading": "しゅじく", "meaning": "trục chính"}, {"term": "下図", "reading": "かず", "meaning": "hình dưới"}]'::jsonb, 1);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 2, 'ボール盤とは、工作物を主軸に取り付け、工作物を回転させながら加工を行う工作機械である。', 'Máy khoan là máy công cụ gá phôi lên trục chính và gia công trong khi quay phôi.', FALSE, 'Sai ở “工作物を主軸に取り付け、工作物を回転”. Đó là nguyên lý cơ bản của máy tiện. Máy khoan giữ phôi cố định; mũi khoan lắp trên trục chính quay và tiến vào phôi để tạo lỗ.', '[{"term": "ボール盤", "reading": "ボールばん", "meaning": "máy khoan"}, {"term": "工作物", "reading": "こうさくぶつ", "meaning": "phôi"}, {"term": "取り付ける", "reading": "とりつける", "meaning": "gá/lắp"}, {"term": "回転", "reading": "かいてん", "meaning": "quay"}, {"term": "加工", "reading": "かこう", "meaning": "gia công"}]'::jsonb, 2);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 3, '下図に示す回路における抵抗Rは、10Ωである。', 'Điện trở R trong mạch ở hình dưới là 10 Ω.', FALSE, 'Sai ở giá trị “10Ω” của R. Nguồn 10 V cấp dòng 1 A qua R nối tiếp điện trở 5 Ω. Điện trở tổng Rt = U/I = 10/1 = 10 Ω. Vì Rt = R + 5 Ω nên R = 10 − 5 = 5 Ω. Phân biệt điện trở toàn mạch với điện trở cần tìm.', '[{"term": "回路", "reading": "かいろ", "meaning": "mạch điện"}, {"term": "抵抗", "reading": "ていこう", "meaning": "điện trở"}, {"term": "直列", "reading": "ちょくれつ", "meaning": "nối tiếp"}, {"term": "電圧", "reading": "でんあつ", "meaning": "điện áp"}, {"term": "電流", "reading": "でんりゅう", "meaning": "dòng điện"}]'::jsonb, 3);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 4, '三相誘導電動機は、3本の電源線のうち、いずれかの2本の接続を入れ替えると電動機の軸の回転方向が逆になる。', 'Với động cơ cảm ứng ba pha, đổi chỗ kết nối của hai dây bất kỳ trong ba dây nguồn sẽ làm chiều quay của trục động cơ đảo ngược.', TRUE, 'Đổi chỗ hai pha làm đảo thứ tự pha và chiều quay từ trường, nên đảo chiều động cơ. Đổi cả ba dây theo vòng luân phiên vẫn giữ thứ tự pha nên không tạo tác dụng tương tự. Với motor được cấp từ biến tần, việc điều khiển chiều còn phải theo cấu hình và hướng dẫn của bộ truyền động.', '[{"term": "三相誘導電動機", "reading": "さんそうゆうどうでんどうき", "meaning": "động cơ cảm ứng ba pha"}, {"term": "電源線", "reading": "でんげんせん", "meaning": "dây nguồn"}, {"term": "接続", "reading": "せつぞく", "meaning": "kết nối"}, {"term": "回転方向", "reading": "かいてんほうこう", "meaning": "chiều quay"}, {"term": "入れ替える", "reading": "いれかえる", "meaning": "đổi chỗ"}]'::jsonb, 4);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 5, '事後保全とは、設備に故障が発生した段階で、その故障を取り除く保全活動である。', 'Bảo trì sau hỏng là hoạt động bảo trì loại bỏ hỏng hóc ở giai đoạn thiết bị đã phát sinh hỏng.', TRUE, 'Đúng: 事後保全 được thực hiện sau khi xảy ra hỏng để khôi phục chức năng. Ví dụ thay cảm biến đã hỏng khiến máy không hoạt động. Bảo trì phòng ngừa thực hiện trước hỏng; bảo trì cải tiến thay đổi thiết bị nhằm giảm khả năng hỏng hoặc nâng tính năng.', '[{"term": "事後保全", "reading": "じごほぜん", "meaning": "bảo trì sau hỏng"}, {"term": "設備", "reading": "せつび", "meaning": "thiết bị"}, {"term": "故障", "reading": "こしょう", "meaning": "hỏng hóc"}, {"term": "取り除く", "reading": "とりのぞく", "meaning": "loại bỏ"}, {"term": "保全活動", "reading": "ほぜんかつどう", "meaning": "hoạt động bảo trì"}]'::jsonb, 5);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 6, '故障モードの例として、変形や腐食などが挙げられる。', 'Ví dụ về dạng hỏng gồm biến dạng và ăn mòn.', TRUE, '故障モード là dạng/biểu hiện hỏng của đối tượng, chẳng hạn biến dạng, ăn mòn, nứt hoặc đứt. Phân biệt với nguyên nhân hỏng: tải quá lớn có thể gây biến dạng; môi trường ẩm hoặc hóa chất có thể gây ăn mòn. Dạng hỏng mô tả hỏng như thế nào; nguyên nhân giải thích vì sao hỏng.', '[{"term": "故障モード", "reading": "こしょうモード", "meaning": "dạng hỏng"}, {"term": "変形", "reading": "へんけい", "meaning": "biến dạng"}, {"term": "腐食", "reading": "ふしょく", "meaning": "ăn mòn"}, {"term": "例", "reading": "れい", "meaning": "ví dụ"}]'::jsonb, 6);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 7, '下図のバスタブ曲線において、Ａは摩耗故障期、Ｂは偶発故障期である。', 'Trong đường cong bồn tắm ở hình dưới, A là giai đoạn hỏng do hao mòn và B là giai đoạn hỏng ngẫu nhiên.', FALSE, 'Sai ở việc đảo tên hai vùng. A là đoạn giữa có suất hỏng gần ổn định, tức 偶発故障期 (hỏng ngẫu nhiên). B là đoạn cuối có suất hỏng tăng, tức 摩耗故障期 (hỏng do hao mòn). Đoạn đầu được ghi 初期故障期: suất hỏng giảm theo thời gian. Trục đứng là 故障率; trục ngang là 稼働時間.', '[{"term": "バスタブ曲線", "reading": "バスタブきょくせん", "meaning": "đường cong bồn tắm"}, {"term": "摩耗故障期", "reading": "まもうこしょうき", "meaning": "giai đoạn hỏng do hao mòn"}, {"term": "偶発故障期", "reading": "ぐうはつこしょうき", "meaning": "giai đoạn hỏng ngẫu nhiên"}, {"term": "初期故障期", "reading": "しょきこしょうき", "meaning": "giai đoạn hỏng sớm"}, {"term": "稼働時間", "reading": "かどうじかん", "meaning": "thời gian vận hành"}]'::jsonb, 7);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 8, '設備履歴簿には、設備の故障の内容や、修理に要した費用などの記録を残す。', 'Sổ lịch sử thiết bị lưu các ghi chép như nội dung hỏng của thiết bị và chi phí cần cho sửa chữa.', TRUE, 'Đúng: sổ lịch sử giữ dữ liệu hỏng, sửa chữa, thay thế và các chi phí liên quan để theo dõi thiết bị. Những dữ liệu này giúp nhận ra hỏng lặp lại, lập kế hoạch bảo trì và đánh giá phương án sửa/thay. Nó khác hướng dẫn công việc chuẩn, vốn quy định cách thực hiện thao tác.', '[{"term": "設備履歴簿", "reading": "せつびりれきぼ", "meaning": "sổ lịch sử thiết bị"}, {"term": "修理", "reading": "しゅうり", "meaning": "sửa chữa"}, {"term": "費用", "reading": "ひよう", "meaning": "chi phí"}, {"term": "記録", "reading": "きろく", "meaning": "ghi chép"}, {"term": "要した", "reading": "ようした", "meaning": "đã cần/đã tiêu tốn"}]'::jsonb, 8);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 9, '下図は、特性要因図である。', 'Hình dưới là sơ đồ nguyên nhân–kết quả.', FALSE, 'Sai ở “特性要因図”. Hình có các cột giảm dần và đường tích lũy tăng lên, là biểu đồ Pareto (パレート図), giúp ưu tiên nhóm đóng góp lớn. Sơ đồ nguyên nhân–kết quả có dạng xương cá, các nhánh yếu tố dẫn vào kết quả. Không suy tên biểu đồ theo số câu của năm khác.', '[{"term": "特性要因図", "reading": "とくせいよういんず", "meaning": "sơ đồ nguyên nhân–kết quả"}, {"term": "パレート図", "reading": "パレートず", "meaning": "biểu đồ Pareto"}, {"term": "累積", "reading": "るいせき", "meaning": "tích lũy"}, {"term": "下図", "reading": "かず", "meaning": "hình dưới"}]'::jsonb, 9);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 10, '作業標準書とは、作業者が作業にかかった時間を、作業のたびに記入するものである。', 'Hướng dẫn công việc chuẩn là tài liệu mà người thao tác ghi thời gian đã dùng cho công việc mỗi lần thực hiện.', FALSE, 'Sai ở phần “時間を、作業のたびに記入”. Đó là ghi chép thời gian công việc. 作業標準書 quy định trình tự, điều kiện, điểm kiểm tra và lưu ý để thực hiện thống nhất. Ví dụ quy trình thay dao CNC cần nêu các bước và tiêu chí xác nhận, chứ không chỉ ghi thời gian đã làm.', '[{"term": "作業標準書", "reading": "さぎょうひょうじゅんしょ", "meaning": "hướng dẫn công việc chuẩn"}, {"term": "作業者", "reading": "さぎょうしゃ", "meaning": "người thao tác"}, {"term": "時間", "reading": "じかん", "meaning": "thời gian"}, {"term": "記入", "reading": "きにゅう", "meaning": "ghi vào"}]'::jsonb, 10);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 11, '鉄は、銅よりも耐食性に優れる。', 'Sắt có khả năng chống ăn mòn tốt hơn đồng.', FALSE, 'Sai ở “鉄は、銅よりも耐食性に優れる”. Trong môi trường khí quyển thông thường, sắt dễ gỉ hơn đồng. Khả năng chống ăn mòn thực còn phụ thuộc môi trường, hợp kim và xử lý bề mặt; không lấy đặc tính của thép không gỉ để thay cho sắt trong nhận định cơ bản này.', '[{"term": "鉄", "reading": "てつ", "meaning": "sắt"}, {"term": "銅", "reading": "どう", "meaning": "đồng"}, {"term": "耐食性", "reading": "たいしょくせい", "meaning": "khả năng chống ăn mòn"}, {"term": "優れる", "reading": "すぐれる", "meaning": "tốt hơn/vượt trội"}]'::jsonb, 11);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 12, 'ステンレス鋼は、鉄と亜鉛の合金である。', 'Thép không gỉ là hợp kim của sắt và kẽm.', FALSE, 'Sai ở “鉄と亜鉛”. Crom là nguyên tố đặc trưng tạo tính chống gỉ nhờ màng thụ động; một số loại còn chứa niken. Kẽm thường được dùng mạ bảo vệ thép, nhưng thép mạ kẽm không đồng nghĩa với thép không gỉ.', '[{"term": "ステンレス鋼", "reading": "ステンレスこう", "meaning": "thép không gỉ"}, {"term": "鉄", "reading": "てつ", "meaning": "sắt"}, {"term": "亜鉛", "reading": "あえん", "meaning": "kẽm"}, {"term": "合金", "reading": "ごうきん", "meaning": "hợp kim"}, {"term": "クロム", "reading": "クロム", "meaning": "crom"}]'::jsonb, 12);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 13, '金属の熱処理は、加熱温度や冷却速度などを調節することにより、性質や金属組織を改良する加工方法である。', 'Nhiệt luyện kim loại là phương pháp gia công cải thiện tính chất và tổ chức kim loại bằng cách điều chỉnh nhiệt độ nung, tốc độ làm nguội và các yếu tố khác.', TRUE, 'Nhiệt luyện điều chỉnh chu trình nung, giữ nhiệt và làm nguội để đạt tổ chức và tính chất cần thiết. Ủ có thể làm mềm và giảm ứng suất; tôi thường tăng độ cứng; ram điều chỉnh tính chất sau tôi. Vì vậy không mặc định mọi nhiệt luyện đều làm vật liệu cứng hơn.', '[{"term": "熱処理", "reading": "ねつしょり", "meaning": "nhiệt luyện"}, {"term": "加熱温度", "reading": "かねつおんど", "meaning": "nhiệt độ nung"}, {"term": "冷却速度", "reading": "れいきゃくそくど", "meaning": "tốc độ làm nguội"}, {"term": "金属組織", "reading": "きんぞくそしき", "meaning": "tổ chức kim loại"}, {"term": "調節", "reading": "ちょうせつ", "meaning": "điều chỉnh"}]'::jsonb, 13);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 14, '労働安全衛生法は、労働者の安全と健康を確保するために、事業主等の責任を定めた法律である。', 'Luật An toàn và Vệ sinh Lao động là luật quy định trách nhiệm của người sử dụng lao động và các bên liên quan nhằm bảo đảm an toàn và sức khỏe của người lao động.', TRUE, 'Nhận định đúng về mục đích và trách nhiệm cơ bản. Luật đặt trách nhiệm bảo đảm an toàn, sức khỏe tại nơi làm việc cho bên sử dụng lao động và các chủ thể liên quan. Trong ôn thi, ghi nhớ đối tượng được bảo vệ là người lao động. [Nguồn Bộ Y tế, Lao động và Phúc lợi Nhật](https://www.mhlw.go.jp/content/11201250/001046756.pdf).', '[{"term": "労働安全衛生法", "reading": "ろうどうあんぜんえいせいほう", "meaning": "Luật An toàn và Vệ sinh Lao động"}, {"term": "労働者", "reading": "ろうどうしゃ", "meaning": "người lao động"}, {"term": "事業主", "reading": "じぎょうぬし", "meaning": "người sử dụng lao động/chủ doanh nghiệp"}, {"term": "責任", "reading": "せきにん", "meaning": "trách nhiệm"}, {"term": "確保", "reading": "かくほ", "meaning": "bảo đảm"}]'::jsonb, 14);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 15, '5Sにおける整理とは、必要なものと不要なものを区分し、不要なものをなくすことをいう。', 'Trong 5S, sàng lọc là phân loại vật cần và không cần, rồi loại bỏ vật không cần.', TRUE, 'Đúng vì đề dùng 整理 (sàng lọc). Phân biệt 整頓 (sắp xếp): bố trí những vật cần dùng tại vị trí quy định để dễ tìm, lấy và trả lại. Loại bỏ dao hỏng là 整理; đặt dao còn dùng vào ô có nhãn là 整頓.', '[{"term": "整理", "reading": "せいり", "meaning": "sàng lọc"}, {"term": "整頓", "reading": "せいとん", "meaning": "sắp xếp"}, {"term": "必要", "reading": "ひつよう", "meaning": "cần thiết"}, {"term": "不要", "reading": "ふよう", "meaning": "không cần"}, {"term": "区分", "reading": "くぶん", "meaning": "phân loại"}]'::jsonb, 15);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 16, 'ブラシレスモータとは、整流子で界磁方向を切り替えるモータである。', 'Động cơ không chổi than là động cơ chuyển đổi hướng từ trường bằng cổ góp.', FALSE, 'Sai ở “整流子”. Động cơ không chổi than không dùng bộ tiếp xúc cơ khí chổi than–cổ góp để chuyển mạch; mạch điện tử điều khiển cấp dòng các pha theo vị trí rotor. Cổ góp cơ khí thuộc động cơ có chổi than. [Nguồn Oriental Motor](https://www.orientalmotor.co.jp/system/files/document/download/catalog/G-217.pdf?brandCode=EX&senimotoId=6&seriesCode=&serviceTypeNo=19).', '[{"term": "ブラシレスモータ", "reading": "ブラシレスモータ", "meaning": "động cơ không chổi than"}, {"term": "整流子", "reading": "せいりゅうし", "meaning": "cổ góp"}, {"term": "界磁方向", "reading": "かいじほうこう", "meaning": "hướng từ trường kích từ"}, {"term": "切り替える", "reading": "きりかえる", "meaning": "chuyển đổi"}]'::jsonb, 16);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 17, 'サーマルリレーは、電動機の過負荷や拘束状態の大電流による焼損を防止するために使用される。', 'Rơ-le nhiệt được dùng để ngăn cháy hỏng do dòng lớn trong tình trạng quá tải hoặc kẹt rotor của động cơ.', TRUE, 'Rơ-le nhiệt phát hiện dòng quá tải kéo dài và tác động mạch điều khiển để công tắc tơ ngắt động cơ. Kẹt rotor có thể gây dòng lớn kéo dài, nên thuộc tình trạng cần bảo vệ. Nó không thay thiết bị bảo vệ ngắn mạch tức thời; lựa chọn và cài đặt phải phù hợp motor.', '[{"term": "サーマルリレー", "reading": "サーマルリレー", "meaning": "rơ-le nhiệt"}, {"term": "過負荷", "reading": "かふか", "meaning": "quá tải"}, {"term": "拘束状態", "reading": "こうそくじょうたい", "meaning": "tình trạng kẹt rotor"}, {"term": "大電流", "reading": "だいでんりゅう", "meaning": "dòng lớn"}, {"term": "焼損", "reading": "しょうそん", "meaning": "cháy hỏng"}]'::jsonb, 17);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 18, 'シーケンス制御とは、あらかじめ定められた順序、または手続きに従って制御の各段階を逐次進めていく制御方式である。', 'Điều khiển trình tự là phương thức lần lượt tiến hành các giai đoạn điều khiển theo thứ tự hoặc thủ tục đã định trước.', TRUE, 'Đúng: sequence control tiến qua các bước dựa trên thứ tự, điều kiện, tín hiệu hoặc timer quy định. Ví dụ kẹp phôi xác nhận xong → trục chính chạy → chạy dao → dừng và nhả kẹp. Không phải chỉ đơn giản chạy theo thời gian; điều kiện liên động cũng có thể quyết định chuyển bước.', '[{"term": "シーケンス制御", "reading": "シーケンスせいぎょ", "meaning": "điều khiển trình tự"}, {"term": "順序", "reading": "じゅんじょ", "meaning": "thứ tự"}, {"term": "手続き", "reading": "てつづき", "meaning": "thủ tục"}, {"term": "段階", "reading": "だんかい", "meaning": "giai đoạn"}, {"term": "逐次", "reading": "ちくじ", "meaning": "lần lượt"}]'::jsonb, 18);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 19, 'エンコーダは、入力信号を増幅させる機能をもつ。', 'Encoder có chức năng khuếch đại tín hiệu đầu vào.', FALSE, 'Sai ở “増幅”. Encoder mã hóa vị trí, góc hoặc chuyển động thành tín hiệu, thường là xung hoặc mã vị trí. Trong máy CNC, bộ điều khiển sử dụng tín hiệu encoder để xác định vị trí/tốc độ. Bộ khuếch đại (アンプ) mới có chức năng tăng tín hiệu; các mạch phụ trợ bên trong encoder không đổi chức năng chính này.', '[{"term": "エンコーダ", "reading": "エンコーダ", "meaning": "bộ mã hóa"}, {"term": "入力信号", "reading": "にゅうりょくしんごう", "meaning": "tín hiệu đầu vào"}, {"term": "増幅", "reading": "ぞうふく", "meaning": "khuếch đại"}, {"term": "機能", "reading": "きのう", "meaning": "chức năng"}, {"term": "位置", "reading": "いち", "meaning": "vị trí"}]'::jsonb, 19);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 20, '静電誘導とは、抵抗体に電流を流すと、ジュール熱が発生することである。', 'Cảm ứng tĩnh điện là việc nhiệt Joule sinh ra khi cho dòng điện chạy qua vật có điện trở.', FALSE, 'Sai ở tên “静電誘導”. Mô tả là sự phát nhiệt Joule: Q = I²Rt với dòng và điện trở không đổi. Cảm ứng tĩnh điện là sự phân bố lại điện tích trong vật dẫn dưới tác dụng điện trường của vật mang điện ở gần, có thể xảy ra mà không tiếp xúc. Không nhầm với cảm ứng điện từ hay phát nhiệt điện trở.', '[{"term": "静電誘導", "reading": "せいでんゆうどう", "meaning": "cảm ứng tĩnh điện"}, {"term": "抵抗体", "reading": "ていこうたい", "meaning": "vật/phần tử có điện trở"}, {"term": "電流", "reading": "でんりゅう", "meaning": "dòng điện"}, {"term": "ジュール熱", "reading": "ジュールねつ", "meaning": "nhiệt Joule"}, {"term": "発生", "reading": "はっせい", "meaning": "sinh ra"}]'::jsonb, 20);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 21, '原子は、1つの原子核と1つの電子により構成される。', 'Nguyên tử được cấu tạo từ một hạt nhân và một electron.', FALSE, 'Sai ở “1つの電子” khi phát biểu chung cho mọi nguyên tử. Nguyên tử có một hạt nhân và các electron; số electron của nguyên tử trung hòa bằng số proton. Hydro trung hòa có một electron, nhưng heli trung hòa có hai, nên không dùng trường hợp hydro để định nghĩa mọi nguyên tử.', '[{"term": "原子", "reading": "げんし", "meaning": "nguyên tử"}, {"term": "原子核", "reading": "げんしかく", "meaning": "hạt nhân nguyên tử"}, {"term": "電子", "reading": "でんし", "meaning": "electron"}, {"term": "構成", "reading": "こうせい", "meaning": "cấu tạo"}, {"term": "中性", "reading": "ちゅうせい", "meaning": "trung hòa"}]'::jsonb, 21);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 22, '1秒間に1Cの電荷が通過するとき、電流の大きさは、1Aである。', 'Khi điện lượng 1 C đi qua trong 1 giây, cường độ dòng điện là 1 A.', TRUE, 'Dòng điện trung bình I = ΔQ/Δt. Thay số I = 1 C/1 s = 1 A. C (coulomb) là điện lượng; A (ampere) là dòng điện; s là giây. Không nhầm điện lượng với công suất điện.', '[{"term": "秒間", "reading": "びょうかん", "meaning": "khoảng thời gian tính bằng giây"}, {"term": "電荷", "reading": "でんか", "meaning": "điện tích/điện lượng"}, {"term": "通過", "reading": "つうか", "meaning": "đi qua"}, {"term": "電流", "reading": "でんりゅう", "meaning": "dòng điện"}, {"term": "大きさ", "reading": "おおきさ", "meaning": "độ lớn"}]'::jsonb, 22);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 23, '論理回路において、入力をA、Bとした場合、「NOR」は、「A・B」である。', 'Trong mạch logic, khi đầu vào là A và B, “NOR” là “A・B”.', FALSE, 'Sai ở “A・B”: đó là AND. NOR là phủ định của OR: Y = ¬(A + B). Bảng chân trị: 00 → 1; 01 → 0; 10 → 0; 11 → 0. Đầu ra NOR chỉ bằng 1 khi cả hai đầu vào bằng 0; không nhầm NOR với NAND = ¬(A·B).', '[{"term": "論理回路", "reading": "ろんりかいろ", "meaning": "mạch logic"}, {"term": "入力", "reading": "にゅうりょく", "meaning": "đầu vào"}, {"term": "NOR", "reading": "ノア", "meaning": "phép phủ định HOẶC"}, {"term": "否定", "reading": "ひてい", "meaning": "phủ định"}, {"term": "出力", "reading": "しゅつりょく", "meaning": "đầu ra"}]'::jsonb, 23);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 24, '絶縁抵抗計のＥ端子の極性は、＋である。', 'Cực tính đầu E của máy đo điện trở cách điện là dương (+).', TRUE, 'Đúng: E/EARTH là cực dương của điện áp thử, còn L/LINE là cực âm theo quy định được HIOKI dẫn từ JIS C 1302. Câu này hỏi E, nên đáp án khác câu hỏi L của các năm 2025 và 2026. Không suy cực tính theo màu dây. [Nguồn HIOKI](https://hiokisupport.zendesk.com/hc/ja/articles/9370517176335).', '[{"term": "絶縁抵抗計", "reading": "ぜつえんていこうけい", "meaning": "máy đo điện trở cách điện"}, {"term": "Ｅ端子", "reading": "イーたんし", "meaning": "đầu E/EARTH"}, {"term": "極性", "reading": "きょくせい", "meaning": "cực tính"}, {"term": "正極", "reading": "せいきょく", "meaning": "cực dương"}, {"term": "負極", "reading": "ふきょく", "meaning": "cực âm"}]'::jsonb, 24);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 25, 'クランプメータは、電流値を測定できる。', 'Ampe kìm có thể đo giá trị dòng điện.', TRUE, 'Ampe kìm cảm nhận từ trường do dòng điện trong dây tạo ra để suy ra dòng, không cần cắt mạch và mắc nối tiếp như ampe kế thông thường. Đo dòng tải thường kẹp một dây dẫn; kẹp cả dây đi và về làm các từ trường có thể triệt tiêu. Khả năng đo AC/DC phụ thuộc loại máy. [Nguồn HIOKI](https://www.hioki.com/jp-ja/learning/test-tools/clamp-meter.html).', '[{"term": "クランプメータ", "reading": "クランプメータ", "meaning": "ampe kìm"}, {"term": "電流値", "reading": "でんりゅうち", "meaning": "giá trị dòng điện"}, {"term": "測定", "reading": "そくてい", "meaning": "đo"}, {"term": "磁界", "reading": "じかい", "meaning": "từ trường"}]'::jsonb, 25);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 26, '混触とは、変圧器内で低圧電路の結線が高圧電路の結線と接触し、低圧電路側に高圧が発生することである。', 'Chạm lẫn cao áp–hạ áp là hiện tượng trong máy biến áp, dây đấu của mạch hạ áp tiếp xúc dây đấu của mạch cao áp, khiến điện áp cao xuất hiện phía hạ áp.', TRUE, 'Đúng: 混触 là tiếp xúc ngoài ý muốn giữa các mạch có cấp điện áp khác nhau; câu nêu trường hợp cao áp và hạ áp trong máy biến áp. Hỏng cách điện có thể đưa điện áp nguy hiểm sang phía vốn chỉ làm việc ở hạ áp. Phân biệt với 地絡 (chạm đất) và ngắn mạch giữa các pha cùng mạch.', '[{"term": "混触", "reading": "こんしょく", "meaning": "chạm lẫn giữa mạch khác cấp điện áp"}, {"term": "変圧器", "reading": "へんあつき", "meaning": "máy biến áp"}, {"term": "低圧電路", "reading": "ていあつでんろ", "meaning": "mạch hạ áp"}, {"term": "高圧電路", "reading": "こうあつでんろ", "meaning": "mạch cao áp"}, {"term": "結線", "reading": "けっせん", "meaning": "đấu dây"}]'::jsonb, 26);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 27, '圧着端子に記されている「2－6」は、2mm²の電線を用いて、6mmのネジで取り付けることを意味する。', 'Ký hiệu “2－6” trên đầu cốt ép có nghĩa là dùng dây điện 2 mm² và lắp bằng vít 6 mm.', TRUE, 'Đúng theo quy cách trong đề: 2 chỉ tiết diện danh định dây 2 mm², còn 6 chỉ cỡ vít 6 mm (M6). Không hiểu 2 là đường kính dây hoặc 6 là tiết diện dây. Khi chọn đầu cốt, cần đúng loại dây và dụng cụ ép tương ứng.', '[{"term": "圧着端子", "reading": "あっちゃくたんし", "meaning": "đầu cốt ép"}, {"term": "記されている", "reading": "しるされている", "meaning": "được ghi"}, {"term": "電線", "reading": "でんせん", "meaning": "dây điện"}, {"term": "ネジ", "reading": "ネジ", "meaning": "vít"}, {"term": "取り付ける", "reading": "とりつける", "meaning": "lắp/gắn"}]'::jsonb, 27);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 28, 'アルミニウムや銅は、導電材料である。', 'Nhôm và đồng là vật liệu dẫn điện.', TRUE, 'Đúng: đồng và nhôm có tính dẫn điện tốt và được dùng làm dây hoặc thanh dẫn. Vật liệu cách điện thông thường là cao su, nhựa hoặc gốm phù hợp. Lớp oxit trên nhôm không làm thay đổi việc lõi nhôm là vật dẫn trong ngữ cảnh này.', '[{"term": "アルミニウム", "reading": "アルミニウム", "meaning": "nhôm"}, {"term": "銅", "reading": "どう", "meaning": "đồng"}, {"term": "導電材料", "reading": "どうでんざいりょう", "meaning": "vật liệu dẫn điện"}, {"term": "絶縁材料", "reading": "ぜつえんざいりょう", "meaning": "vật liệu cách điện"}]'::jsonb, 28);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 29, 'ＪＩＳにおいて、下図は「接地」の電気用図記号である。', 'Theo JIS, hình dưới là ký hiệu điện của “nối đất”.', TRUE, 'Hình có nét dẫn xuống và ba nét ngang ngắn dần là ký hiệu nối đất. Nó đánh dấu điểm nối với đất trên sơ đồ. Không nhầm với ký hiệu nguồn pin, tiếp điểm hoặc các ký hiệu mass/chassis có hình khác.', '[{"term": "ＪＩＳ", "reading": "ジス", "meaning": "tiêu chuẩn công nghiệp Nhật"}, {"term": "接地", "reading": "せっち", "meaning": "nối đất"}, {"term": "電気用図記号", "reading": "でんきようずきごう", "meaning": "ký hiệu trên sơ đồ điện"}, {"term": "下図", "reading": "かず", "meaning": "hình dưới"}]'::jsonb, 29);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2024', '第1回', 30, 'ＪＩＳにおいて、下図は「ＮＰＮ型トランジスタ」の電気用図記号である。', 'Theo JIS, hình dưới là ký hiệu điện của “transistor loại NPN”.', FALSE, 'Sai ở “ＮＰＮ型”. Mũi tên trên nhánh emitter trong hình hướng vào phía base, nên ký hiệu là PNP. NPN có mũi tên emitter hướng ra. Đọc chiều mũi tên trong hình, không học đáp án theo số câu; mũi tên thuộc emitter, không thuộc collector.', '[{"term": "ＮＰＮ型", "reading": "エヌピーエヌがた", "meaning": "loại NPN"}, {"term": "トランジスタ", "reading": "トランジスタ", "meaning": "transistor"}, {"term": "電気用図記号", "reading": "でんきようずきごう", "meaning": "ký hiệu trên sơ đồ điện"}, {"term": "矢印", "reading": "やじるし", "meaning": "mũi tên"}, {"term": "エミッタ", "reading": "エミッタ", "meaning": "emitter/cực phát"}]'::jsonb, 30);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 1, '下図に示す工作機械は、旋盤である。', 'Máy công cụ trong hình dưới là máy tiện.', FALSE, 'Sai ở “旋盤”. Hình là máy khoan bàn/đứng (ボール盤): trục chính và mũi khoan thẳng đứng, bàn đỡ phôi bên dưới. Máy tiện có trục chính và phôi quay theo phương ngang trong kiểu máy thông dụng ở đề.', '[{"term": "工作機械", "reading": "こうさくきかい", "meaning": "máy công cụ"}, {"term": "旋盤", "reading": "せんばん", "meaning": "máy tiện"}, {"term": "下図", "reading": "かず", "meaning": "hình dưới"}, {"term": "ボール盤", "reading": "ボールばん", "meaning": "máy khoan"}]'::jsonb, 31);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 2, 'フライス盤とは、工作物を主軸に取り付け、工作物を回転させながら加工を行う工作機械である。', 'Máy phay là máy công cụ gá phôi lên trục chính và gia công trong khi quay phôi.', FALSE, 'Sai ở “工作物を主軸に取り付け、工作物を回転”. Đó là nguyên lý điển hình của máy tiện. Trên máy phay, dao phay được trục chính dẫn động quay; phôi gá trên bàn máy và chuyển động chạy dao tương đối với dao.', '[{"term": "フライス盤", "reading": "フライスばん", "meaning": "máy phay"}, {"term": "工作物", "reading": "こうさくぶつ", "meaning": "phôi"}, {"term": "主軸", "reading": "しゅじく", "meaning": "trục chính"}, {"term": "取り付ける", "reading": "とりつける", "meaning": "gá/lắp"}, {"term": "回転", "reading": "かいてん", "meaning": "quay"}]'::jsonb, 32);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 3, '下図に示す回路の合成抵抗は、50Ωである。', 'Điện trở tương đương của mạch trong hình dưới là 50 Ω.', TRUE, 'Hai điện trở 100 Ω mắc song song. Công thức: 1/Rt = 1/R1 + 1/R2; Rt = (R1 × R2)/(R1 + R2) = (100 × 100)/(100 + 100) = 50 Ω. Hai nhánh có cùng hai nút đầu và cuối, nên không cộng thành 200 Ω.', '[{"term": "回路", "reading": "かいろ", "meaning": "mạch điện"}, {"term": "合成抵抗", "reading": "ごうせいていこう", "meaning": "điện trở tương đương"}, {"term": "並列", "reading": "へいれつ", "meaning": "song song"}, {"term": "抵抗", "reading": "ていこう", "meaning": "điện trở"}]'::jsonb, 33);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 4, '60Hzで使用している三相誘導電動機を50Hzで使用すると、回転数は6/5倍になる。', 'Khi dùng động cơ cảm ứng ba pha đang sử dụng ở 60 Hz sang 50 Hz, tốc độ quay trở thành 6/5 lần.', FALSE, 'Sai ở “6/5倍”. Với số cực p không đổi, tốc độ đồng bộ ns = 120f/p (vòng/phút). ns50/ns60 = 50/60 = 5/6, tức giảm còn khoảng 83,3%. Ví dụ p = 4: 1800 → 1500 vòng/phút. Tốc độ rotor n = (1 − s)ns còn phụ thuộc độ trượt s, nên tỉ lệ tốc độ rotor được hiểu gần đúng khi độ trượt tương đương.', '[{"term": "三相誘導電動機", "reading": "さんそうゆうどうでんどうき", "meaning": "động cơ cảm ứng ba pha"}, {"term": "回転数", "reading": "かいてんすう", "meaning": "tốc độ quay"}, {"term": "周波数", "reading": "しゅうはすう", "meaning": "tần số"}, {"term": "倍", "reading": "ばい", "meaning": "lần"}]'::jsonb, 34);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 5, '事後保全は、予め定められた計画に沿って設備を停止して、分解・点検・整備をする保全方式である。', 'Bảo trì sau hỏng là phương thức dừng thiết bị theo kế hoạch định trước để tháo rời, kiểm tra và bảo dưỡng.', FALSE, 'Sai ở cách định nghĩa “事後保全”. Bảo trì sau hỏng được tiến hành sau khi xuất hiện hỏng hóc để khôi phục chức năng. Dừng máy theo kế hoạch để tháo kiểm tra và bảo dưỡng trước khi hỏng thuộc bảo trì phòng ngừa có kế hoạch, thường là bảo trì định kỳ.', '[{"term": "事後保全", "reading": "じごほぜん", "meaning": "bảo trì sau hỏng"}, {"term": "予め", "reading": "あらかじめ", "meaning": "trước/định trước"}, {"term": "分解", "reading": "ぶんかい", "meaning": "tháo rời"}, {"term": "点検", "reading": "てんけん", "meaning": "kiểm tra"}, {"term": "整備", "reading": "せいび", "meaning": "bảo dưỡng"}]'::jsonb, 35);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 6, '保全性の良い設備の例として、清掃、点検、給油などの定期整備が容易な設備が挙げられる。', 'Ví dụ về thiết bị có tính bảo trì tốt là thiết bị dễ thực hiện bảo dưỡng định kỳ như vệ sinh, kiểm tra và cấp dầu.', TRUE, 'Tính bảo trì (maintainability) tốt giúp thao tác bảo dưỡng hoặc khôi phục máy dễ và nhanh. Vị trí bôi trơn dễ tiếp cận, cửa kiểm tra thuận tiện và bộ phận dễ tháo thay là các ví dụ. Đừng nhầm tính bảo trì với độ tin cậy: một bên là dễ bảo trì, một bên là ít hỏng.', '[{"term": "保全性", "reading": "ほぜんせい", "meaning": "tính dễ bảo trì"}, {"term": "清掃", "reading": "せいそう", "meaning": "vệ sinh"}, {"term": "給油", "reading": "きゅうゆ", "meaning": "cấp dầu/bôi trơn"}, {"term": "定期整備", "reading": "ていきせいび", "meaning": "bảo dưỡng định kỳ"}, {"term": "容易", "reading": "ようい", "meaning": "dễ dàng"}]'::jsonb, 36);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 7, 'バスタブ曲線は、時間経過による機械や装置などの故障率の変化を表すグラフである。', 'Đường cong bồn tắm là đồ thị biểu diễn sự thay đổi của suất hỏng của máy và thiết bị theo thời gian.', TRUE, 'Đường cong có ba vùng điển hình: hỏng sớm có suất hỏng giảm, hỏng ngẫu nhiên có suất hỏng gần ổn định, và hỏng do hao mòn có suất hỏng tăng. Trục dọc là suất hỏng, không phải tổng số lần hỏng tích lũy.', '[{"term": "バスタブ曲線", "reading": "バスタブきょくせん", "meaning": "đường cong bồn tắm"}, {"term": "時間経過", "reading": "じかんけいか", "meaning": "sự trôi qua của thời gian"}, {"term": "故障率", "reading": "こしょうりつ", "meaning": "suất hỏng"}, {"term": "装置", "reading": "そうち", "meaning": "thiết bị"}]'::jsonb, 37);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 8, '腐食とは、金属が他の固体と接触して発生する摩擦力により、表面が損傷したり、すり減る現象である。', 'Ăn mòn là hiện tượng bề mặt bị hư hại hoặc mòn đi do lực ma sát phát sinh khi kim loại tiếp xúc với vật rắn khác.', FALSE, 'Sai ở việc gọi ma sát làm mất vật liệu là “腐食”. Mô tả này là mài mòn (摩耗). Ăn mòn là sự suy thoái vật liệu do phản ứng hóa học hoặc điện hóa với môi trường, ví dụ thép bị gỉ. Trong bảo trì, cần phân biệt vết mòn do tiếp xúc với gỉ do môi trường.', '[{"term": "腐食", "reading": "ふしょく", "meaning": "ăn mòn"}, {"term": "固体", "reading": "こたい", "meaning": "vật rắn"}, {"term": "摩擦力", "reading": "まさつりょく", "meaning": "lực ma sát"}, {"term": "損傷", "reading": "そんしょう", "meaning": "hư hại"}, {"term": "摩耗", "reading": "まもう", "meaning": "mài mòn"}]'::jsonb, 38);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 9, '下図に示すような品質管理の手法は、特性要因図である。', 'Phương pháp quản lý chất lượng như trong hình dưới là sơ đồ nguyên nhân–kết quả.', TRUE, 'Các nhánh 人, 機械, 方法, 材料 lần lượt là con người, máy móc, phương pháp, vật liệu; chúng hướng tới 結果 (kết quả). Đây là sơ đồ xương cá/đặc tính–yếu tố, dùng tổ chức các nguyên nhân có thể gây ra một kết quả. Sơ đồ giúp đặt giả thuyết; cần dữ liệu kiểm chứng để xác định nguyên nhân thật.', '[{"term": "品質管理", "reading": "ひんしつかんり", "meaning": "quản lý chất lượng"}, {"term": "特性要因図", "reading": "とくせいよういんず", "meaning": "sơ đồ nguyên nhân–kết quả"}, {"term": "方法", "reading": "ほうほう", "meaning": "phương pháp"}, {"term": "材料", "reading": "ざいりょう", "meaning": "vật liệu"}, {"term": "結果", "reading": "けっか", "meaning": "kết quả"}]'::jsonb, 39);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 10, '作業標準書とは、作業者が作業にかかった時間を、作業のたびに記入するものである。', 'Hướng dẫn công việc chuẩn là tài liệu mà người thao tác ghi thời gian đã dùng cho công việc mỗi lần thực hiện.', FALSE, 'Sai ở “時間を、作業のたびに記入”. Đó là một dạng nhật ký/bảng ghi thời gian thực hiện. 作業標準書 quy định trình tự, điều kiện, điểm kiểm tra và những điểm cần chú ý để thực hiện công việc thống nhất. Ví dụ thay dao CNC có bước dừng máy, xác nhận dao, lắp và kiểm tra theo chuẩn.', '[{"term": "作業標準書", "reading": "さぎょうひょうじゅんしょ", "meaning": "hướng dẫn công việc chuẩn"}, {"term": "作業者", "reading": "さぎょうしゃ", "meaning": "người thao tác"}, {"term": "記入", "reading": "きにゅう", "meaning": "ghi vào"}, {"term": "時間", "reading": "じかん", "meaning": "thời gian"}]'::jsonb, 40);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 11, 'アルミニウムは、銅より熱伝導率が小さい。', 'Nhôm có hệ số dẫn nhiệt nhỏ hơn đồng.', TRUE, 'Trong điều kiện thông thường, đồng dẫn nhiệt tốt hơn nhôm. Vì vậy nhận định “nhôm nhỏ hơn đồng” đúng. Nhôm vẫn dẫn nhiệt tốt và nhẹ, thường dùng làm tản nhiệt. So sánh này nói về hệ số dẫn nhiệt, không phải khối lượng riêng hay điện trở.', '[{"term": "アルミニウム", "reading": "アルミニウム", "meaning": "nhôm"}, {"term": "銅", "reading": "どう", "meaning": "đồng"}, {"term": "熱伝導率", "reading": "ねつでんどうりつ", "meaning": "hệ số dẫn nhiệt"}, {"term": "小さい", "reading": "ちいさい", "meaning": "nhỏ hơn"}]'::jsonb, 41);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 12, '合金鋼は、薄い金属の板を複数枚重ね合わせることで、耐荷重性を強化したものである。', 'Thép hợp kim là vật được tăng khả năng chịu tải bằng cách chồng nhiều tấm kim loại mỏng lên nhau.', FALSE, 'Sai ở “薄い金属の板を複数枚重ね合わせる”. Thép hợp kim là thép có thêm các nguyên tố hợp kim như Cr, Ni, Mo để điều chỉnh tính chất. Chồng tấm là kết cấu nhiều lớp, không phải định nghĩa thép hợp kim.', '[{"term": "合金鋼", "reading": "ごうきんこう", "meaning": "thép hợp kim"}, {"term": "金属", "reading": "きんぞく", "meaning": "kim loại"}, {"term": "複数枚", "reading": "ふくすうまい", "meaning": "nhiều tấm"}, {"term": "耐荷重性", "reading": "たいかじゅうせい", "meaning": "khả năng chịu tải"}, {"term": "強化", "reading": "きょうか", "meaning": "tăng cường"}]'::jsonb, 42);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 13, '鋼の焼なましは、鋼を軟化させ、加工しやすくする熱処理の方法である。', 'Ủ thép là phương pháp nhiệt luyện làm mềm thép và giúp thép dễ gia công.', TRUE, 'Ủ sử dụng chu trình nung, giữ nhiệt và làm nguội phù hợp, thường nguội chậm, để làm mềm và điều chỉnh tổ chức. Nhờ vậy phôi dễ gia công hơn và có thể giảm ứng suất dư. Đừng nhầm với tôi (焼入れ), thường nhằm tăng độ cứng.', '[{"term": "鋼", "reading": "はがね", "meaning": "thép"}, {"term": "焼なまし", "reading": "やきなまし", "meaning": "ủ"}, {"term": "軟化", "reading": "なんか", "meaning": "làm mềm"}, {"term": "加工", "reading": "かこう", "meaning": "gia công"}, {"term": "熱処理", "reading": "ねつしょり", "meaning": "nhiệt luyện"}]'::jsonb, 43);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 14, '労働災害とは、火災や地震など、設備の損傷原因となる災害のことである。', 'Tai nạn lao động là thảm họa như cháy hoặc động đất gây hư hại thiết bị.', FALSE, 'Sai ở việc định nghĩa chỉ bằng hư hại thiết bị. 労働災害 chỉ tổn hại đối với người lao động như bị thương, mắc bệnh hoặc tử vong có nguyên nhân liên quan công việc. Cháy hoặc động đất có thể dẫn tới tai nạn lao động trong hoàn cảnh làm việc, nhưng hư hại máy đơn thuần không phải định nghĩa này.', '[{"term": "労働災害", "reading": "ろうどうさいがい", "meaning": "tai nạn/tổn hại lao động"}, {"term": "火災", "reading": "かさい", "meaning": "hỏa hoạn"}, {"term": "地震", "reading": "じしん", "meaning": "động đất"}, {"term": "損傷原因", "reading": "そんしょうげんいん", "meaning": "nguyên nhân gây hư hại"}]'::jsonb, 44);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 15, '5Sにおける整頓とは、必要なものと不要なものを区分し、不要なものをなくすことをいう。', 'Trong 5S, sắp xếp là phân loại vật cần và không cần, rồi loại bỏ vật không cần.', FALSE, 'Sai ở tên “整頓”. Nội dung này là 整理 (sàng lọc). 整頓 là bố trí vật cần dùng đúng vị trí, dễ tìm, dễ lấy và dễ trả lại. Ví dụ loại bỏ dao hỏng là 整理; đánh số vị trí cho dao còn dùng là 整頓.', '[{"term": "整頓", "reading": "せいとん", "meaning": "sắp xếp"}, {"term": "整理", "reading": "せいり", "meaning": "sàng lọc"}, {"term": "必要", "reading": "ひつよう", "meaning": "cần thiết"}, {"term": "不要", "reading": "ふよう", "meaning": "không cần"}, {"term": "区分", "reading": "くぶん", "meaning": "phân loại"}]'::jsonb, 45);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 16, 'サーボモータに適した制御は、クローズドループ方式である。', 'Điều khiển phù hợp với động cơ servo là phương thức vòng kín.', TRUE, 'Vòng kín đo giá trị thực bằng encoder hoặc cảm biến rồi phản hồi để giảm sai lệch so với lệnh. Điều khiển vị trí trục CNC là ví dụ quen thuộc: lệnh vị trí → bộ điều khiển → động cơ → encoder → phản hồi. Đây là mô hình cơ bản phù hợp với servo trong đề.', '[{"term": "サーボモータ", "reading": "サーボモータ", "meaning": "động cơ servo"}, {"term": "制御", "reading": "せいぎょ", "meaning": "điều khiển"}, {"term": "クローズドループ", "reading": "クローズドループ", "meaning": "vòng kín"}, {"term": "方式", "reading": "ほうしき", "meaning": "phương thức"}, {"term": "適した", "reading": "てきした", "meaning": "phù hợp"}]'::jsonb, 46);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 17, 'インバータは、出力の周波数を変えることはできない。', 'Biến tần không thể thay đổi tần số đầu ra.', FALSE, 'Sai ở “変えることはできない”. Biến tần điều chỉnh tần số đầu ra và điện áp phù hợp để điều khiển động cơ. Vì tốc độ đồng bộ phụ thuộc tần số, thay đổi tần số cho phép điều chỉnh tốc độ. Không nhầm tần số nguồn đầu vào cố định với tần số đầu ra do biến tần tạo ra.', '[{"term": "インバータ", "reading": "インバータ", "meaning": "biến tần"}, {"term": "出力", "reading": "しゅつりょく", "meaning": "đầu ra"}, {"term": "周波数", "reading": "しゅうはすう", "meaning": "tần số"}, {"term": "変える", "reading": "かえる", "meaning": "thay đổi"}]'::jsonb, 47);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 18, 'フィードフォワード制御とは、目標値、外乱などの情報に基づいて、操作量を決定する制御方式である。', 'Điều khiển truyền thẳng là phương thức xác định đại lượng tác động điều khiển dựa trên thông tin như giá trị mục tiêu và nhiễu ngoài.', TRUE, 'Feedforward dùng thông tin về mục tiêu hoặc nhiễu đã biết/đo được để tính tác động trước khi sai lệch đầu ra xuất hiện. Ví dụ tăng bù mô-men khi dự kiến tải tăng. Feedback dùng đầu ra thực và sai lệch; hai phương thức có thể kết hợp.', '[{"term": "フィードフォワード制御", "reading": "フィードフォワードせいぎょ", "meaning": "điều khiển truyền thẳng"}, {"term": "目標値", "reading": "もくひょうち", "meaning": "giá trị mục tiêu"}, {"term": "外乱", "reading": "がいらん", "meaning": "nhiễu ngoài"}, {"term": "操作量", "reading": "そうさりょう", "meaning": "đại lượng tác động điều khiển"}, {"term": "情報", "reading": "じょうほう", "meaning": "thông tin"}]'::jsonb, 48);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 19, '温度センサの1つとして、熱電対が挙げられる。', 'Cặp nhiệt điện là một loại cảm biến nhiệt độ.', TRUE, 'Cặp nhiệt điện dùng hai vật liệu dẫn điện khác nhau; chênh lệch nhiệt độ giữa mối đo và đầu tham chiếu tạo sức điện động nhiệt (hiệu ứng Seebeck). Thiết bị đo sử dụng điện áp này cùng bù đầu lạnh để suy ra nhiệt độ. Không nhầm với cảm biến điện trở nhiệt.', '[{"term": "温度センサ", "reading": "おんどセンサ", "meaning": "cảm biến nhiệt độ"}, {"term": "熱電対", "reading": "ねつでんつい", "meaning": "cặp nhiệt điện"}, {"term": "挙げられる", "reading": "あげられる", "meaning": "được nêu làm ví dụ"}, {"term": "温度", "reading": "おんど", "meaning": "nhiệt độ"}]'::jsonb, 49);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 20, '導線（電線）に電流を流したとき、導線の周囲に発生する磁界（磁束）の向きは、電流が流れる方向に対して左回りとなる。', 'Khi cho dòng điện chạy qua dây dẫn (dây điện), chiều từ trường (từ thông) sinh ra quanh dây là ngược chiều kim đồng hồ so với hướng dòng điện chạy.', FALSE, 'Sai ở việc quy định “左回り” như một quy tắc cố định. Dùng quy tắc bàn tay phải: ngón cái chỉ chiều dòng điện quy ước, các ngón còn lại chỉ chiều đường sức từ. Nhìn theo chiều dòng điện đi ra xa người quan sát thì từ trường quay thuận chiều kim đồng hồ; nhìn dòng điện đi về phía mình thì thấy ngược chiều kim đồng hồ. Luôn xác định hướng nhìn.', '[{"term": "導線", "reading": "どうせん", "meaning": "dây dẫn"}, {"term": "電流", "reading": "でんりゅう", "meaning": "dòng điện"}, {"term": "磁界", "reading": "じかい", "meaning": "từ trường"}, {"term": "磁束", "reading": "じそく", "meaning": "từ thông"}, {"term": "左回り", "reading": "ひだりまわり", "meaning": "ngược chiều kim đồng hồ"}]'::jsonb, 50);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 21, '原子は、原子核と電子により構成される。', 'Nguyên tử được cấu tạo từ hạt nhân và electron.', TRUE, 'Hạt nhân ở trung tâm gồm proton và, với đa số đồng vị, neutron; electron tồn tại ở vùng xung quanh hạt nhân. Nhận định chỉ nêu hai thành phần lớn của nguyên tử nên đúng. Không nhầm electron mang điện âm với proton mang điện dương.', '[{"term": "原子", "reading": "げんし", "meaning": "nguyên tử"}, {"term": "原子核", "reading": "げんしかく", "meaning": "hạt nhân nguyên tử"}, {"term": "電子", "reading": "でんし", "meaning": "electron"}, {"term": "構成", "reading": "こうせい", "meaning": "cấu tạo"}]'::jsonb, 51);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 22, '直流回路において、10Vの電圧で10Aの電流が流れたとき電力は、10Wである。', 'Trong mạch một chiều, khi dòng 10 A chạy với điện áp 10 V, công suất là 10 W.', FALSE, 'Sai ở “10W”. Công suất điện một chiều P = U × I = 10 × 10 = 100 W. Đơn vị: V × A = W. Điện năng mới là E = P × t; không thêm thời gian vào phép tính công suất.', '[{"term": "直流回路", "reading": "ちょくりゅうかいろ", "meaning": "mạch một chiều"}, {"term": "電圧", "reading": "でんあつ", "meaning": "điện áp"}, {"term": "電流", "reading": "でんりゅう", "meaning": "dòng điện"}, {"term": "電力", "reading": "でんりょく", "meaning": "công suất điện"}]'::jsonb, 52);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 23, '論理回路において、入力をA、Bとした場合、「ＯＲ」は、「A＋B」である。', 'Trong mạch logic, khi các đầu vào là A và B, “OR” là “A＋B”.', TRUE, 'Dấu + trong đại số Boolean là phép HOẶC, không phải phép cộng số học thông thường. Bảng: 0 OR 0 = 0; 0 OR 1 = 1; 1 OR 0 = 1; 1 OR 1 = 1. Đầu ra bằng 1 nếu ít nhất một đầu vào bằng 1; AND thường viết A·B.', '[{"term": "論理回路", "reading": "ろんりかいろ", "meaning": "mạch logic"}, {"term": "入力", "reading": "にゅうりょく", "meaning": "đầu vào"}, {"term": "ＯＲ", "reading": "オア", "meaning": "phép HOẶC"}, {"term": "出力", "reading": "しゅつりょく", "meaning": "đầu ra"}]'::jsonb, 53);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 24, '絶縁抵抗計のＬ端子の極性は、＋である。', 'Cực tính của đầu L trên máy đo điện trở cách điện là dương (+).', FALSE, 'Sai ở “＋”. Trong máy đo điện trở cách điện theo quy định JIS được HIOKI giải thích, L/LINE là cực âm (−), E/EARTH là cực dương (+) của điện áp thử. Không suy cực tính chỉ từ màu đỏ/đen của dây đo. [Nguồn kỹ thuật HIOKI](https://hiokisupport.zendesk.com/hc/ja/articles/9370517176335).', '[{"term": "絶縁抵抗計", "reading": "ぜつえんていこうけい", "meaning": "máy đo điện trở cách điện"}, {"term": "端子", "reading": "たんし", "meaning": "đầu nối"}, {"term": "極性", "reading": "きょくせい", "meaning": "cực tính"}, {"term": "負極", "reading": "ふきょく", "meaning": "cực âm"}, {"term": "正極", "reading": "せいきょく", "meaning": "cực dương"}]'::jsonb, 54);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 25, 'オシロスコープは、物体の温度を測定する計測器である。', 'Máy hiện sóng là dụng cụ đo nhiệt độ của vật thể.', FALSE, 'Sai ở “温度を測定”. Máy hiện sóng hiển thị dạng sóng tín hiệu, thường điện áp theo thời gian; có thể đọc biên độ, chu kỳ, tần số và độ trễ. Nhiệt kế hoặc cảm biến nhiệt dùng đo nhiệt độ. Máy hiện sóng có thể xem tín hiệu từ cảm biến nhưng không vì vậy trở thành nhiệt kế trực tiếp.', '[{"term": "オシロスコープ", "reading": "オシロスコープ", "meaning": "máy hiện sóng"}, {"term": "物体", "reading": "ぶったい", "meaning": "vật thể"}, {"term": "測定", "reading": "そくてい", "meaning": "đo"}, {"term": "計測器", "reading": "けいそくき", "meaning": "dụng cụ đo"}, {"term": "波形", "reading": "はけい", "meaning": "dạng sóng"}]'::jsonb, 55);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 26, '地絡とは、2つの相、または3つの相の線間が負荷を通さずに接触した状態のことである。', 'Chạm đất là trạng thái các dây giữa hai pha hoặc ba pha tiếp xúc nhau mà không đi qua tải.', FALSE, 'Sai ở “地絡”. Tiếp xúc giữa các pha không qua tải là ngắn mạch pha (短絡). 地絡 là dây mang điện tiếp xúc đất hoặc phần kim loại nối đất do cách điện hỏng. Ví dụ dây pha cọ vỏ motor nối đất là chạm đất; hai dây pha chạm nhau là ngắn mạch.', '[{"term": "地絡", "reading": "ちらく", "meaning": "chạm đất"}, {"term": "相", "reading": "そう", "meaning": "pha"}, {"term": "線間", "reading": "せんかん", "meaning": "giữa các dây"}, {"term": "負荷", "reading": "ふか", "meaning": "tải"}, {"term": "短絡", "reading": "たんらく", "meaning": "ngắn mạch"}]'::jsonb, 56);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 27, '下図に示す銅線用裸圧着端子のうち、R形はaの方である。', 'Trong các đầu cốt ép trần dùng cho dây đồng ở hình dưới, loại R là hình a.', TRUE, 'Hình a có vòng tròn kín để luồn vít qua, là đầu cốt tròn R形. Hình b có khe mở dạng chạc, là loại chữ Y. Nhận diện theo hình lỗ bắt vít, không theo phần ống ép dây. Giữ nguyên nhãn a/b của hình gốc.', '[{"term": "銅線用", "reading": "どうせんよう", "meaning": "dùng cho dây đồng"}, {"term": "裸圧着端子", "reading": "はだかあっちゃくたんし", "meaning": "đầu cốt ép trần"}, {"term": "R形", "reading": "アールがた", "meaning": "loại vòng R"}, {"term": "圧着", "reading": "あっちゃく", "meaning": "ép/bấm cốt"}]'::jsonb, 57);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 28, '天然ゴムは、導電材料である。', 'Cao su thiên nhiên là vật liệu dẫn điện.', FALSE, 'Sai ở “導電材料”. Cao su thiên nhiên thông thường là vật liệu cách điện. Có thể tạo cao su dẫn điện bằng chất độn hoặc công thức đặc biệt, nhưng đó không phải tính chất cơ bản mà câu này hỏi.', '[{"term": "天然ゴム", "reading": "てんねんゴム", "meaning": "cao su thiên nhiên"}, {"term": "導電材料", "reading": "どうでんざいりょう", "meaning": "vật liệu dẫn điện"}, {"term": "絶縁材料", "reading": "ぜつえんざいりょう", "meaning": "vật liệu cách điện"}, {"term": "天然", "reading": "てんねん", "meaning": "tự nhiên"}]'::jsonb, 58);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 29, 'JISにおいて、下図は「接地」の電気用図記号である。', 'Theo JIS, hình dưới là ký hiệu điện của “nối đất”.', TRUE, 'Ký hiệu có một nét dẫn xuống và ba nét ngang ngắn dần là ký hiệu nối đất. Nó chỉ điểm nối tới đất; không phải ký hiệu tiếp điểm hay nguồn pin. Khi đọc sơ đồ bảo trì, phân biệt nối đất với các ký hiệu mass/chassis khác.', '[{"term": "接地", "reading": "せっち", "meaning": "nối đất"}, {"term": "電気用図記号", "reading": "でんきようずきごう", "meaning": "ký hiệu trên sơ đồ điện"}, {"term": "JIS", "reading": "ジス", "meaning": "tiêu chuẩn công nghiệp Nhật"}, {"term": "下図", "reading": "かず", "meaning": "hình dưới"}]'::jsonb, 59);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2025', '第1回', 30, '下図に示すような有接点リレーシーケンス回路図において、「PBS-黒（押しボタンスイッチ-黒）」を押した場合、３番目に点灯するのは「GL（緑ランプ）」である。', 'Trong sơ đồ mạch trình tự rơ-le có tiếp điểm như hình dưới, khi nhấn “PBS-đen (công tắc nút nhấn-đen)”, đèn sáng thứ ba là “GL (đèn xanh lá)”.', TRUE, 'Nhấn PBS làm CR1 hút. Tiếp điểm CR1 tạo tự giữ và cấp điện cho timer T1, đồng thời đóng nhánh WL/CR2. WL sáng trước; CR2 hút rồi tiếp điểm CR2 làm YL sáng thứ hai. Khi T1 đủ 2 giây, tiếp điểm đóng trễ T1 cấp điện cho GL, nên GL sáng thứ ba. Chuỗi là WL → YL → GL; thứ tự hai đèn đầu dựa trên tầng tác động rơ-le, không phải khoảng trễ được ghi riêng. Đường đứng WL–CR2 cho thấy chúng song song, không nối tiếp.', '[{"term": "有接点", "reading": "ゆうせってん", "meaning": "có tiếp điểm"}, {"term": "シーケンス回路図", "reading": "シーケンスかいろず", "meaning": "sơ đồ mạch trình tự"}, {"term": "押しボタン", "reading": "おしボタン", "meaning": "nút nhấn"}, {"term": "点灯", "reading": "てんとう", "meaning": "sáng đèn"}, {"term": "緑ランプ", "reading": "みどりランプ", "meaning": "đèn xanh lá"}]'::jsonb, 60);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 1, '下図に示す工作機械は、旋盤である。', 'Máy công cụ trong hình dưới là máy tiện.', TRUE, 'Hình có ụ đứng, mâm cặp, băng máy, bàn xe dao và ụ động theo trục ngang, đặc trưng của máy tiện. Phôi gá trên trục chính quay, dao thực hiện chạy dao. Hình câu 1 năm 2025 là máy khoan nên không học đáp án theo số câu.', '[{"term": "工作機械", "reading": "こうさくきかい", "meaning": "máy công cụ"}, {"term": "旋盤", "reading": "せんばん", "meaning": "máy tiện"}, {"term": "下図", "reading": "かず", "meaning": "hình dưới"}, {"term": "主軸", "reading": "しゅじく", "meaning": "trục chính"}]'::jsonb, 61);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 2, 'ボール盤とは、工作物を固定して、主軸に取り付けた切削工具を回転させながら穴あけ加工を行う工作機械である。', 'Máy khoan là máy công cụ cố định phôi và gia công lỗ trong khi quay dụng cụ cắt lắp trên trục chính.', TRUE, 'Đúng: phôi được kẹp cố định; mũi khoan trên trục chính quay và tiến vào phôi để tạo lỗ. Cần phân biệt với máy tiện, nơi phôi quay. Máy CNC có thể kết hợp nhiều nguyên công, nhưng câu này hỏi định nghĩa cơ bản của ボール盤.', '[{"term": "ボール盤", "reading": "ボールばん", "meaning": "máy khoan"}, {"term": "工作物", "reading": "こうさくぶつ", "meaning": "phôi"}, {"term": "固定", "reading": "こてい", "meaning": "cố định"}, {"term": "切削工具", "reading": "せっさくこうぐ", "meaning": "dụng cụ cắt"}, {"term": "穴あけ加工", "reading": "あなあけかこう", "meaning": "gia công khoan lỗ"}]'::jsonb, 62);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 3, '下図に示す回路における抵抗Rは、10Ωである。', 'Điện trở R trong mạch ở hình dưới là 10 Ω.', FALSE, 'Sai ở “Rは、10Ω”. Mạch nối tiếp có U = 10 V, I = 1 A và điện trở đã biết 5 Ω. Rt = U/I = 10/1 = 10 Ω; Rt = R + 5 Ω, nên R = 10 − 5 = 5 Ω. 10 Ω là điện trở tổng, không phải R riêng lẻ.', '[{"term": "回路", "reading": "かいろ", "meaning": "mạch điện"}, {"term": "抵抗", "reading": "ていこう", "meaning": "điện trở"}, {"term": "直列", "reading": "ちょくれつ", "meaning": "nối tiếp"}, {"term": "電圧", "reading": "でんあつ", "meaning": "điện áp"}, {"term": "電流", "reading": "でんりゅう", "meaning": "dòng điện"}]'::jsonb, 63);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 4, '60Hzで使用している三相誘導電動機を50Hzで使用すると、回転数は6/5倍になる。', 'Khi dùng động cơ cảm ứng ba pha đang sử dụng ở 60 Hz sang 50 Hz, tốc độ quay trở thành 6/5 lần.', FALSE, 'Sai ở “6/5倍”. Với số cực p không đổi, ns = 120f/p; ns50/ns60 = 50/60 = 5/6, tức giảm còn khoảng 83,3%. Ví dụ động cơ 4 cực: tốc độ đồng bộ 1800 → 1500 vòng/phút. Tốc độ thực n = (1 − s)ns còn phụ thuộc độ trượt, nên chỉ suy ra tỉ lệ rotor gần đúng nếu độ trượt tương đương.', '[{"term": "三相誘導電動機", "reading": "さんそうゆうどうでんどうき", "meaning": "động cơ cảm ứng ba pha"}, {"term": "回転数", "reading": "かいてんすう", "meaning": "tốc độ quay"}, {"term": "周波数", "reading": "しゅうはすう", "meaning": "tần số"}, {"term": "倍", "reading": "ばい", "meaning": "lần"}]'::jsonb, 64);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 5, '改良保全とは、設備の故障を起きにくくしたり、設備の性能や安全性を高める保全である。', 'Bảo trì cải tiến là bảo trì làm thiết bị khó xảy ra hỏng hơn hoặc nâng cao tính năng và độ an toàn của thiết bị.', TRUE, '改良保全 cải tiến cấu tạo, vật liệu hoặc cách vận hành để giảm hỏng và nâng tính năng/an toàn. Ví dụ cải thiện che chắn bụi cho cảm biến hoặc bố trí điểm bôi trơn dễ tiếp cận. Mục tiêu vượt ra ngoài việc chỉ khôi phục trạng thái trước hỏng.', '[{"term": "改良保全", "reading": "かいりょうほぜん", "meaning": "bảo trì cải tiến"}, {"term": "故障", "reading": "こしょう", "meaning": "hỏng hóc"}, {"term": "性能", "reading": "せいのう", "meaning": "tính năng"}, {"term": "安全性", "reading": "あんぜんせい", "meaning": "độ an toàn"}, {"term": "高める", "reading": "たかめる", "meaning": "nâng cao"}]'::jsonb, 65);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 6, '平均故障寿命とは、故障した設備が修理されてから、次に故障するまでの動作時間の平均値である。', 'Tuổi thọ hỏng trung bình là giá trị trung bình của thời gian hoạt động từ khi thiết bị hỏng được sửa chữa đến khi hỏng lần tiếp theo.', FALSE, 'Sai ở tên “平均故障寿命”. Mô tả thời gian hoạt động giữa các hỏng của thiết bị sửa được tương ứng 平均故障間隔 (MTBF). 平均故障寿命 (MTTF) dùng cho thời gian tới hỏng của đối tượng không sửa được. Công thức mẫu: MTBF = tổng thời gian hoạt động/tổng số lần hỏng; MTTF = tổng thời gian tới hỏng/số đối tượng quan sát hỏng trong mẫu đầy đủ. Không cộng thời gian đang sửa vào thời gian hoạt động.', '[{"term": "平均故障寿命", "reading": "へいきんこしょうじゅみょう", "meaning": "tuổi thọ tới hỏng trung bình"}, {"term": "平均故障間隔", "reading": "へいきんこしょうかんかく", "meaning": "thời gian hoạt động trung bình giữa các hỏng"}, {"term": "修理", "reading": "しゅうり", "meaning": "sửa chữa"}, {"term": "動作時間", "reading": "どうさじかん", "meaning": "thời gian hoạt động"}, {"term": "平均値", "reading": "へいきんち", "meaning": "giá trị trung bình"}]'::jsonb, 66);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 7, '予知保全とは、過去の故障実績などを参考にし、一定の周期で点検や検査を行う保全である。', 'Bảo trì dự đoán là bảo trì tham khảo lịch sử hỏng trước đây để kiểm tra hoặc kiểm nghiệm theo chu kỳ cố định.', FALSE, 'Sai ở “一定の周期” dùng làm định nghĩa 予知保全. Kiểm tra theo thời gian định sẵn là bảo trì định kỳ. Bảo trì dự đoán theo dõi tình trạng như rung, nhiệt độ, dầu và xu hướng suy giảm để dự báo hỏng, quyết định thời điểm can thiệp. Thu thập dữ liệu có thể định kỳ, nhưng tiêu chí quyết định là tình trạng/dự báo, không chỉ lịch.', '[{"term": "予知保全", "reading": "よちほぜん", "meaning": "bảo trì dự đoán"}, {"term": "故障実績", "reading": "こしょうじっせき", "meaning": "lịch sử hỏng"}, {"term": "周期", "reading": "しゅうき", "meaning": "chu kỳ"}, {"term": "点検", "reading": "てんけん", "meaning": "kiểm tra"}, {"term": "検査", "reading": "けんさ", "meaning": "kiểm nghiệm"}]'::jsonb, 67);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 8, 'なぜなぜ分析は、発生した現象を起点として、その現象がなぜ起きたのかを繰り返し調査していくことで、対策を立てる手法である。', 'Phân tích “tại sao–tại sao” là phương pháp lập biện pháp đối phó bằng cách xuất phát từ hiện tượng đã xảy ra và điều tra lặp lại vì sao hiện tượng đó xảy ra.', TRUE, 'Hỏi liên tiếp “vì sao” để đi từ biểu hiện đến nguyên nhân gốc và chọn biện pháp phù hợp. Ví dụ máy dừng → bảo vệ quá tải tác động → tải cơ tăng → ổ trục kẹt → thiếu bôi trơn. Mỗi mắt xích phải có bằng chứng; không bắt buộc dừng đúng năm câu hỏi hay quy lỗi cho người vận hành.', '[{"term": "なぜなぜ分析", "reading": "なぜなぜぶんせき", "meaning": "phân tích tại sao lặp lại"}, {"term": "現象", "reading": "げんしょう", "meaning": "hiện tượng"}, {"term": "起点", "reading": "きてん", "meaning": "điểm xuất phát"}, {"term": "調査", "reading": "ちょうさ", "meaning": "điều tra"}, {"term": "対策", "reading": "たいさく", "meaning": "biện pháp xử lý"}]'::jsonb, 68);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 9, '下図に示すような品質管理の手法は、特性要因図である。', 'Phương pháp quản lý chất lượng như trong hình dưới là sơ đồ nguyên nhân–kết quả.', TRUE, 'Sơ đồ xương cá đưa các yếu tố 人, 機械, 方法, 材料 vào các nhánh dẫn đến 結果. Nó tổ chức nguyên nhân có thể ảnh hưởng tới đặc tính/kết quả cần phân tích. Ví dụ kích thước gia công lệch có thể liên quan dao, gá đặt, chương trình và vật liệu; cần kiểm chứng các giả thuyết bằng dữ liệu.', '[{"term": "品質管理", "reading": "ひんしつかんり", "meaning": "quản lý chất lượng"}, {"term": "特性要因図", "reading": "とくせいよういんず", "meaning": "sơ đồ nguyên nhân–kết quả"}, {"term": "方法", "reading": "ほうほう", "meaning": "phương pháp"}, {"term": "材料", "reading": "ざいりょう", "meaning": "vật liệu"}, {"term": "結果", "reading": "けっか", "meaning": "kết quả"}]'::jsonb, 69);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 10, '正規分布の特徴の1つとして、データが平均値の付近に集積していることが挙げられる。', 'Một đặc điểm của phân bố chuẩn là dữ liệu tập trung quanh giá trị trung bình.', TRUE, 'Mật độ phân bố chuẩn đối xứng quanh trung bình μ và cao nhất ở đó; dữ liệu càng xa trung bình càng ít. Độ lệch chuẩn σ mô tả độ phân tán. Đặc điểm này không có nghĩa mọi bộ số liệu gia công đều là phân bố chuẩn; phải kiểm tra dữ liệu thực.', '[{"term": "正規分布", "reading": "せいきぶんぷ", "meaning": "phân bố chuẩn"}, {"term": "特徴", "reading": "とくちょう", "meaning": "đặc điểm"}, {"term": "平均値", "reading": "へいきんち", "meaning": "giá trị trung bình"}, {"term": "付近", "reading": "ふきん", "meaning": "vùng lân cận"}, {"term": "集積", "reading": "しゅうせき", "meaning": "tập trung"}]'::jsonb, 70);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 11, '一般的に鉄は、銅よりも耐食性に優れる。', 'Nhìn chung, sắt có khả năng chống ăn mòn tốt hơn đồng.', FALSE, 'Sai ở “鉄は、銅よりも耐食性に優れる”. Trong môi trường khí quyển thông thường, sắt dễ gỉ hơn đồng. Đồng có thể tạo lớp sản phẩm bề mặt tương đối bảo vệ. Độ ăn mòn thực còn phụ thuộc môi trường và hợp kim; câu hỏi là so sánh cơ bản sắt với đồng, không phải thép không gỉ.', '[{"term": "一般的", "reading": "いっぱんてき", "meaning": "nhìn chung"}, {"term": "鉄", "reading": "てつ", "meaning": "sắt"}, {"term": "銅", "reading": "どう", "meaning": "đồng"}, {"term": "耐食性", "reading": "たいしょくせい", "meaning": "khả năng chống ăn mòn"}, {"term": "優れる", "reading": "すぐれる", "meaning": "tốt hơn/vượt trội"}]'::jsonb, 71);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 12, 'ステンレス鋼は、鉄にニッケルと亜鉛を加えて性質を改良したものである。', 'Thép không gỉ là thép được cải thiện tính chất bằng cách thêm niken và kẽm vào sắt.', FALSE, 'Sai ở “ニッケルと亜鉛”. Thành phần đặc trưng để chống gỉ là crom (クロム), tạo màng thụ động trên bề mặt; một số loại còn chứa niken. Không phải mọi thép không gỉ đều có niken, và kẽm không thay crom trong định nghĩa này.', '[{"term": "ステンレス鋼", "reading": "ステンレスこう", "meaning": "thép không gỉ"}, {"term": "ニッケル", "reading": "ニッケル", "meaning": "niken"}, {"term": "亜鉛", "reading": "あえん", "meaning": "kẽm"}, {"term": "性質", "reading": "せいしつ", "meaning": "tính chất"}, {"term": "クロム", "reading": "クロム", "meaning": "crom"}]'::jsonb, 72);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 13, '金属の熱処理は、加熱温度や冷却速度などを調節することにより、性質や金属組織を改良する加工方法である。', 'Nhiệt luyện kim loại là phương pháp gia công cải thiện tính chất và tổ chức kim loại bằng cách điều chỉnh nhiệt độ nung, tốc độ làm nguội và các yếu tố khác.', TRUE, 'Chu trình nung, giữ nhiệt và nguội làm thay đổi tổ chức và tính chất vật liệu. Các phương pháp như ủ, tôi, ram phục vụ những mục tiêu khác nhau. Không thể suy rằng nhiệt luyện lúc nào cũng tăng độ cứng: ủ có thể làm mềm, còn tôi có thể tăng độ cứng.', '[{"term": "熱処理", "reading": "ねつしょり", "meaning": "nhiệt luyện"}, {"term": "加熱温度", "reading": "かねつおんど", "meaning": "nhiệt độ nung"}, {"term": "冷却速度", "reading": "れいきゃくそくど", "meaning": "tốc độ làm nguội"}, {"term": "金属組織", "reading": "きんぞくそしき", "meaning": "tổ chức kim loại"}, {"term": "調節", "reading": "ちょうせつ", "meaning": "điều chỉnh"}]'::jsonb, 73);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 14, '労働災害とは、労働者の就業に係る建設物や設備などにより、または作業行動その他の業務に起因して、労働者が負傷し、疾病にかかり、または死亡することをいう。', 'Tai nạn/tổn hại lao động là việc người lao động bị thương, mắc bệnh hoặc tử vong do công trình, thiết bị liên quan đến việc làm, hoặc do hành vi làm việc và các hoạt động nghiệp vụ khác.', TRUE, 'Nhận định xác định tổn hại đối với người và quan hệ nguyên nhân với công việc. Vì vậy khác câu 14 năm 2025 chỉ mô tả hư hại thiết bị. Đây là diễn giải nội dung câu ôn thi; việc xác định quyền lợi của một vụ việc cụ thể cần căn cứ riêng.', '[{"term": "労働災害", "reading": "ろうどうさいがい", "meaning": "tai nạn/tổn hại lao động"}, {"term": "労働者", "reading": "ろうどうしゃ", "meaning": "người lao động"}, {"term": "就業", "reading": "しゅうぎょう", "meaning": "làm việc"}, {"term": "負傷", "reading": "ふしょう", "meaning": "bị thương"}, {"term": "疾病", "reading": "しっぺい", "meaning": "bệnh tật"}, {"term": "起因", "reading": "きいん", "meaning": "có nguyên nhân từ"}]'::jsonb, 74);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 15, '5Sにおける整頓とは、必要なものと不要なものを区分し、不要なものをなくすことをいう。', 'Trong 5S, sắp xếp là phân loại vật cần và không cần, rồi loại bỏ vật không cần.', FALSE, 'Sai ở “整頓”; mô tả là 整理 (sàng lọc). 整頓 là đặt vật cần dùng vào vị trí quy định để dễ tìm, lấy và trả lại. Năm chữ S: 整理 sàng lọc, 整頓 sắp xếp, 清掃 sạch sẽ, 清潔 duy trì sạch và chuẩn, 躾 rèn nề nếp.', '[{"term": "整頓", "reading": "せいとん", "meaning": "sắp xếp"}, {"term": "整理", "reading": "せいり", "meaning": "sàng lọc"}, {"term": "必要", "reading": "ひつよう", "meaning": "cần thiết"}, {"term": "不要", "reading": "ふよう", "meaning": "không cần"}, {"term": "区分", "reading": "くぶん", "meaning": "phân loại"}]'::jsonb, 75);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 16, 'オープンループ方式で制御されるモータは、サーボモータと呼ばれる。', 'Động cơ được điều khiển bằng phương thức vòng hở được gọi là động cơ servo.', FALSE, 'Sai ở việc đồng nhất servo với “オープンループ”. Điều khiển servo cơ bản dùng phản hồi (vòng kín) để điều chỉnh vị trí, tốc độ hoặc mô-men theo lệnh. Vòng hở không dùng giá trị đầu ra đo được để sửa sai lệch; động cơ bước vận hành vòng hở là ví dụ thường gặp trong học cơ bản.', '[{"term": "オープンループ", "reading": "オープンループ", "meaning": "vòng hở"}, {"term": "制御", "reading": "せいぎょ", "meaning": "điều khiển"}, {"term": "サーボモータ", "reading": "サーボモータ", "meaning": "động cơ servo"}, {"term": "方式", "reading": "ほうしき", "meaning": "phương thức"}, {"term": "呼ばれる", "reading": "よばれる", "meaning": "được gọi là"}]'::jsonb, 76);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 17, '電磁開閉器は、電磁接触器から熱動過負荷継電器を外したものである。', 'Khởi động từ là bộ được tạo bằng cách bỏ rơ-le quá tải nhiệt khỏi công tắc tơ.', FALSE, 'Sai ở “外した”. 電磁開閉器 là tổ hợp 電磁接触器 (công tắc tơ) và 熱動過負荷継電器 (rơ-le quá tải nhiệt). Công tắc tơ đóng cắt, rơ-le nhiệt phát hiện quá tải để điều khiển ngắt; không được nhầm bộ khởi động từ với công tắc tơ đơn lẻ. [Nguồn kỹ thuật OMRON](https://www.ia.omron.com/support/guide/753/explanation_of_terms.html).', '[{"term": "電磁開閉器", "reading": "でんじかいへいき", "meaning": "khởi động từ"}, {"term": "電磁接触器", "reading": "でんじせっしょくき", "meaning": "công tắc tơ"}, {"term": "熱動過負荷継電器", "reading": "ねつどうかふかけいでんき", "meaning": "rơ-le quá tải nhiệt"}, {"term": "外す", "reading": "はずす", "meaning": "tháo bỏ"}]'::jsonb, 77);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 18, 'フィードフォワード制御とは、比例動作、積分動作および微分動作の3つの動作を含む制御方式である。', 'Điều khiển truyền thẳng là phương thức điều khiển gồm ba tác động: tỉ lệ, tích phân và vi phân.', FALSE, 'Sai ở tên “フィードフォワード”. Ba tác động P, I, D tạo điều khiển PID, thường dùng trong vòng phản hồi. Feedforward tính tác động từ mục tiêu/nhiễu. Dạng PID lý tưởng: u(t) = Kp·e(t) + Ki·∫e(t)dt + Kd·de(t)/dt, với e là sai lệch; không phải định nghĩa feedforward.', '[{"term": "フィードフォワード制御", "reading": "フィードフォワードせいぎょ", "meaning": "điều khiển truyền thẳng"}, {"term": "比例動作", "reading": "ひれいどうさ", "meaning": "tác động tỉ lệ"}, {"term": "積分動作", "reading": "せきぶんどうさ", "meaning": "tác động tích phân"}, {"term": "微分動作", "reading": "びぶんどうさ", "meaning": "tác động vi phân"}, {"term": "制御方式", "reading": "せいぎょほうしき", "meaning": "phương thức điều khiển"}]'::jsonb, 78);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 19, '温度センサの1つとして、熱電対が挙げられる。', 'Cặp nhiệt điện là một loại cảm biến nhiệt độ.', TRUE, 'Cặp nhiệt điện dùng hai vật liệu dẫn điện khác nhau để tạo sức điện động phụ thuộc chênh lệch nhiệt độ giữa mối đo và đầu tham chiếu. Bộ đo kết hợp bù đầu lạnh để suy ra nhiệt độ mối đo. Cảm biến này thường dùng theo dõi nhiệt trong máy và lò.', '[{"term": "温度センサ", "reading": "おんどセンサ", "meaning": "cảm biến nhiệt độ"}, {"term": "熱電対", "reading": "ねつでんつい", "meaning": "cặp nhiệt điện"}, {"term": "挙げられる", "reading": "あげられる", "meaning": "được nêu làm ví dụ"}, {"term": "温度", "reading": "おんど", "meaning": "nhiệt độ"}]'::jsonb, 79);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 20, 'ジュールの法則とは、電流が流れると電流の大きさ、抵抗の大きさ、電流の流れた時間に応じた熱が発生するという法則である。', 'Định luật Joule nói rằng khi dòng điện chạy, nhiệt sinh ra phụ thuộc vào cường độ dòng điện, điện trở và thời gian dòng điện chạy.', TRUE, 'Với I và R không đổi: Q = I²Rt, Q tính bằng J, I bằng A, R bằng Ω, t bằng s. Công suất nhiệt P = I²R. Ví dụ I = 2 A, R = 5 Ω, t = 10 s thì Q = 2² × 5 × 10 = 200 J. Lưu ý nhiệt tỉ lệ bình phương dòng điện, nên dòng tăng gấp đôi tạo nhiệt gấp bốn nếu R và t giữ nguyên.', '[{"term": "ジュールの法則", "reading": "ジュールのほうそく", "meaning": "định luật Joule"}, {"term": "電流", "reading": "でんりゅう", "meaning": "dòng điện"}, {"term": "抵抗", "reading": "ていこう", "meaning": "điện trở"}, {"term": "熱", "reading": "ねつ", "meaning": "nhiệt"}, {"term": "発生", "reading": "はっせい", "meaning": "sinh ra"}]'::jsonb, 80);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 21, '金属の表面に光を当てると電子が放出される現象を、光電子放出という。', 'Hiện tượng electron được phát ra khi chiếu ánh sáng lên bề mặt kim loại gọi là phát xạ quang electron.', TRUE, 'Đây là phát xạ electron do ánh sáng, một biểu hiện của hiệu ứng quang điện ngoài. Ánh sáng cần có tần số đủ lớn tương ứng công thoát của vật liệu: hf ≥ W. Không phải mọi ánh sáng với bất kỳ tần số nào cũng gây phát xạ; đề nêu tên hiện tượng, không khẳng định điều kiện đó.', '[{"term": "表面", "reading": "ひょうめん", "meaning": "bề mặt"}, {"term": "光", "reading": "ひかり", "meaning": "ánh sáng"}, {"term": "電子", "reading": "でんし", "meaning": "electron"}, {"term": "放出", "reading": "ほうしゅつ", "meaning": "phát ra"}, {"term": "光電子放出", "reading": "こうでんしほうしゅつ", "meaning": "phát xạ quang electron"}]'::jsonb, 81);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 22, '1秒間に1Cの電荷が通過するとき、電流の大きさは、1Aである。', 'Khi điện lượng 1 C đi qua trong 1 giây, cường độ dòng điện là 1 A.', TRUE, 'Dòng điện trung bình I = ΔQ/Δt. Thay số I = 1 C/1 s = 1 A. C là coulomb, đơn vị điện lượng; A là ampere, đơn vị dòng điện. Không nhầm C trong câu với ký hiệu điện dung trong một công thức khác.', '[{"term": "秒間", "reading": "びょうかん", "meaning": "khoảng thời gian tính bằng giây"}, {"term": "電荷", "reading": "でんか", "meaning": "điện tích/điện lượng"}, {"term": "通過", "reading": "つうか", "meaning": "đi qua"}, {"term": "電流", "reading": "でんりゅう", "meaning": "dòng điện"}, {"term": "大きさ", "reading": "おおきさ", "meaning": "độ lớn"}]'::jsonb, 82);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 23, '論理回路において、入力をA、Bとした場合、「ＯＲ」は、「A＋B」である。', 'Trong mạch logic, khi các đầu vào là A và B, “OR” là “A＋B”.', TRUE, 'Đúng theo đại số Boolean: + biểu diễn phép HOẶC. Bảng chân trị: 00 → 0; 01 → 1; 10 → 1; 11 → 1. Một trong hai tín hiệu vào bật là đủ để đầu ra bật. Không cộng 1 + 1 thành 2 như số học.', '[{"term": "論理回路", "reading": "ろんりかいろ", "meaning": "mạch logic"}, {"term": "入力", "reading": "にゅうりょく", "meaning": "đầu vào"}, {"term": "ＯＲ", "reading": "オア", "meaning": "phép HOẶC"}, {"term": "出力", "reading": "しゅつりょく", "meaning": "đầu ra"}]'::jsonb, 83);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 24, '絶縁抵抗計のＬ端子の極性は、＋である。', 'Cực tính của đầu L trên máy đo điện trở cách điện là dương (+).', FALSE, 'Sai ở “＋”. L/LINE là cực âm (−) và E/EARTH là cực dương (+) của điện áp thử trong quy định được HIOKI dẫn từ JIS C 1302. Màu dây không đủ để kết luận cực tính. [Nguồn kỹ thuật HIOKI](https://hiokisupport.zendesk.com/hc/ja/articles/9370517176335).', '[{"term": "絶縁抵抗計", "reading": "ぜつえんていこうけい", "meaning": "máy đo điện trở cách điện"}, {"term": "端子", "reading": "たんし", "meaning": "đầu nối"}, {"term": "極性", "reading": "きょくせい", "meaning": "cực tính"}, {"term": "負極", "reading": "ふきょく", "meaning": "cực âm"}, {"term": "正極", "reading": "せいきょく", "meaning": "cực dương"}]'::jsonb, 84);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 25, '回路の電流を測定する際は、電流計を並列に接続する。', 'Khi đo dòng điện của mạch, mắc ampe kế song song.', FALSE, 'Sai ở “並列”. Ampe kế phải mắc nối tiếp với nhánh cần đo để dòng của nhánh đi qua máy đo. Điện trở trong ampe kế nhỏ; mắc trực tiếp song song nguồn có thể tạo đường gần ngắn mạch. Vôn kế mới mắc song song với hai điểm cần đo điện áp. Ampe kìm đo qua từ trường là phương pháp khác, không đổi quy tắc ampe kế mắc vào mạch.', '[{"term": "電流", "reading": "でんりゅう", "meaning": "dòng điện"}, {"term": "測定", "reading": "そくてい", "meaning": "đo"}, {"term": "電流計", "reading": "でんりゅうけい", "meaning": "ampe kế"}, {"term": "並列", "reading": "へいれつ", "meaning": "song song"}, {"term": "接続", "reading": "せつぞく", "meaning": "kết nối"}, {"term": "直列", "reading": "ちょくれつ", "meaning": "nối tiếp"}]'::jsonb, 85);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 26, '三相誘導電動機の軸受部が異常に高温となる原因として、潤滑剤の過不足が考えられる。', 'Một nguyên nhân làm bộ phận ổ trục của động cơ cảm ứng ba pha nóng bất thường là quá nhiều hoặc quá ít chất bôi trơn.', TRUE, 'Thiếu chất bôi trơn làm tăng tiếp xúc và ma sát; quá nhiều, đặc biệt mỡ, làm tăng cản khuấy và sinh nhiệt. Vì vậy cả thừa lẫn thiếu đều có thể gây nóng. Đây là một nguyên nhân có thể, không phải nguyên nhân duy nhất; còn có sai lắp, lệch trục, hỏng ổ và tải quá lớn.', '[{"term": "三相誘導電動機", "reading": "さんそうゆうどうでんどうき", "meaning": "động cơ cảm ứng ba pha"}, {"term": "軸受部", "reading": "じくうけぶ", "meaning": "bộ phận ổ trục"}, {"term": "高温", "reading": "こうおん", "meaning": "nhiệt độ cao"}, {"term": "潤滑剤", "reading": "じゅんかつざい", "meaning": "chất bôi trơn"}, {"term": "過不足", "reading": "かふそく", "meaning": "thừa hoặc thiếu"}]'::jsonb, 86);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 27, '圧着端子に記されている「2－6」は、2mm²の電線を用いて、6mmのねじで取り付けることを意味する。', 'Ký hiệu “2－6” ghi trên đầu cốt ép có nghĩa là dùng dây điện 2 mm² và lắp bằng vít 6 mm.', TRUE, 'Đúng theo cách ký hiệu trong đề: 2 là tiết diện danh định dây (mm²); 6 chỉ cỡ vít bắt đầu cốt (M6). Không đọc 2 là đường kính dây và không đọc 6 là tiết diện dây. Chọn cốt, dây và dụng cụ ép theo quy cách thực của nhà sản xuất.', '[{"term": "圧着端子", "reading": "あっちゃくたんし", "meaning": "đầu cốt ép"}, {"term": "記されている", "reading": "しるされている", "meaning": "được ghi"}, {"term": "電線", "reading": "でんせん", "meaning": "dây điện"}, {"term": "ねじ", "reading": "ねじ", "meaning": "vít"}, {"term": "取り付ける", "reading": "とりつける", "meaning": "lắp/gắn"}]'::jsonb, 87);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 28, 'アルミニウムや銅は、絶縁材料である。', 'Nhôm và đồng là vật liệu cách điện.', FALSE, 'Sai ở “絶縁材料”. Nhôm và đồng là kim loại dẫn điện, thường dùng làm dây dẫn. Vật liệu cách điện thông thường gồm cao su, nhựa và gốm phù hợp. Lớp oxit trên nhôm có thể có tính cách điện nhưng không biến lõi nhôm thành vật liệu cách điện.', '[{"term": "アルミニウム", "reading": "アルミニウム", "meaning": "nhôm"}, {"term": "銅", "reading": "どう", "meaning": "đồng"}, {"term": "絶縁材料", "reading": "ぜつえんざいりょう", "meaning": "vật liệu cách điện"}, {"term": "導電材料", "reading": "どうでんざいりょう", "meaning": "vật liệu dẫn điện"}]'::jsonb, 88);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 29, 'ＪＩＳにおいて、下図は「リミットスイッチにおけるメーク接点」の電気用図記号である。', 'Theo JIS, hình dưới là ký hiệu điện của “tiếp điểm đóng khi tác động trong công tắc hành trình”.', TRUE, 'Hình thể hiện tiếp điểm đang hở cùng ký hiệu tác động cơ khí của công tắc hành trình. メーク接点 là tiếp điểm thường mở (a/NO): tác động thì đóng mạch. ブレーク接点 là thường đóng (b/NC): tác động thì mở. Đọc trạng thái chưa tác động trước khi suy ra hoạt động.', '[{"term": "リミットスイッチ", "reading": "リミットスイッチ", "meaning": "công tắc hành trình"}, {"term": "メーク接点", "reading": "メークせってん", "meaning": "tiếp điểm thường mở"}, {"term": "電気用図記号", "reading": "でんきようずきごう", "meaning": "ký hiệu trên sơ đồ điện"}, {"term": "接点", "reading": "せってん", "meaning": "tiếp điểm"}, {"term": "JIS", "reading": "ジス", "meaning": "tiêu chuẩn công nghiệp Nhật"}]'::jsonb, 89);
    INSERT INTO certificate_exam_questions (certificate_id, exam_year, exam_round, question_no, question_ja, translation_vi, answer_correct, explanation_vi, vocab_json, sort_order) VALUES (cert_id, '2026', '第1回', 30, 'ＪＩＳにおいて、下図は「ＰＮＰ型トランジスタ」の電気用図記号である。', 'Theo JIS, hình dưới là ký hiệu điện của “transistor loại PNP”.', TRUE, 'Mũi tên trên nhánh emitter hướng vào phía base nên là PNP. Với NPN, mũi tên emitter hướng ra. Nhớ PNP: mũi tên vào; NPN: mũi tên ra. Mũi tên thuộc emitter, không thuộc collector. Hình này là ký hiệu linh kiện transistor, chưa phải sơ đồ đấu cảm biến PNP đầy đủ.', '[{"term": "ＰＮＰ型", "reading": "ピーエヌピーがた", "meaning": "loại PNP"}, {"term": "トランジスタ", "reading": "トランジスタ", "meaning": "transistor"}, {"term": "電気用図記号", "reading": "でんきようずきごう", "meaning": "ký hiệu trên sơ đồ điện"}, {"term": "矢印", "reading": "やじるし", "meaning": "mũi tên"}, {"term": "エミッタ", "reading": "エミッタ", "meaning": "emitter/cực phát"}]'::jsonb, 90);
