-- Certificates feature: denkihozen3 (dien category) — generated from
-- doccument/denkihozen3/*.md via a one-off parsing script

VALUES ('denkihozen3', 'dien', '電気系保全作業', 'Kỹ năng bảo trì điện 3級')
ON CONFLICT (code) DO NOTHING;

DO $$
DECLARE cert_id INT;
BEGIN
    SELECT id INTO cert_id FROM certificates WHERE code = 'denkihozen3';
    DELETE FROM certificate_vocabulary WHERE certificate_id = cert_id;

END $$;

DO $$
DECLARE cert_id INT;
BEGIN
    SELECT id INTO cert_id FROM certificates WHERE code = 'denkihozen3';
    DELETE FROM certificate_exam_questions WHERE certificate_id = cert_id;

END $$;
